fn find_skill(name: &str) -> Option<&'static Skill> {
    SKILLS.iter().find(|s| s.name == name)
}

fn skill_unknown(name: &str) -> i32 {
    eprintln!("error: unknown skill '{name}'");
    eprintln!("run `ilo skill list` to see available skills.");
    1
}

/// Emit a "skill not found" error as a stable JSON envelope on stdout.
/// Used by the `--json` paths of every skill subcommand so agent callers
/// can route on the error without parsing prose.
fn skill_unknown_json(name: &str) -> i32 {
    let v = serde_json::json!({
        "schemaVersion": 1,
        "error": {
            "code": "unknown-skill",
            "message": format!("unknown skill '{name}'"),
            "name": name,
        }
    });
    println!("{}", v);
    1
}

fn skill_list_cmd(as_json: bool) -> i32 {
    if as_json {
        let items: Vec<serde_json::Value> = SKILLS
            .iter()
            .map(|s| {
                serde_json::json!({
                    "name": s.name,
                    "description": s.description,
                    "path": s.path,
                })
            })
            .collect();
        let v = serde_json::json!({
            "schemaVersion": 1,
            "skills": items,
        });
        match serde_json::to_string_pretty(&v) {
            Ok(s) => println!("{}", s),
            Err(e) => {
                eprintln!("error: failed to serialise skill list: {e}");
                return 1;
            }
        }
        return 0;
    }
    for s in SKILLS {
        println!("{:<14} {}", s.name, s.description);
    }
    0
}

fn skill_get_cmd(name: &str, as_json: bool) -> i32 {
    match find_skill(name) {
        Some(s) => {
            if as_json {
                let v = serde_json::json!({
                    "schemaVersion": 1,
                    "name": s.name,
                    "description": s.description,
                    "path": s.path,
                    "content": s.content,
                });
                match serde_json::to_string_pretty(&v) {
                    Ok(out) => println!("{}", out),
                    Err(e) => {
                        eprintln!("error: failed to serialise skill: {e}");
                        return 1;
                    }
                }
            } else {
                print!("{}", s.content);
            }
            0
        }
        None => {
            if as_json {
                skill_unknown_json(name)
            } else {
                skill_unknown(name)
            }
        }
    }
}

fn skill_path_cmd(name: &str, as_json: bool) -> i32 {
    match find_skill(name) {
        Some(s) => {
            if as_json {
                let v = serde_json::json!({
                    "schemaVersion": 1,
                    "name": s.name,
                    "path": s.path,
                });
                println!("{}", v);
            } else {
                println!("{}", s.path);
            }
            0
        }
        None => {
            if as_json {
                skill_unknown_json(name)
            } else {
                skill_unknown(name)
            }
        }
    }
}

fn skill_show_cmd(name: &str, as_json: bool) -> i32 {
    match find_skill(name) {
        Some(s) => {
            if as_json {
                // `show` in JSON mode is identical to `get` in JSON mode —
                // the prose header makes no sense as JSON, so we emit the
                // structured form once.
                let v = serde_json::json!({
                    "schemaVersion": 1,
                    "name": s.name,
                    "description": s.description,
                    "path": s.path,
                    "content": s.content,
                });
                match serde_json::to_string_pretty(&v) {
                    Ok(out) => println!("{}", out),
                    Err(e) => {
                        eprintln!("error: failed to serialise skill: {e}");
                        return 1;
                    }
                }
            } else {
                println!("# {} ({})", s.name, s.path);
                println!();
                println!("{}", s.description);
                println!();
                println!("---");
                println!();
                print!("{}", s.content);
            }
            0
        }
        None => {
            if as_json {
                skill_unknown_json(name)
            } else {
                skill_unknown(name)
            }
        }
    }
}

/// `ilo version` — plain prints `ilo X.Y.Z`, `--json` emits a structured
/// envelope so agent tooling can route on the version without parsing.
/// Emit a deprecation hint when the user loads a `.ilo` file.
/// `.@` is the canonical extension from 0.13.0 onwards; `.ilo` is retained
/// for backward compatibility but nudges users toward the shorter form.
fn maybe_warn_ilo_ext(source_arg: &str) {
    if source_arg.ends_with(".ilo") {
        eprintln!(
            "hint: .ilo extension is deprecated; rename to .@ \
             (saves 1 token/filename on LLM tokenisers)"
        );
    }
}

fn version_cmd(as_json: bool) -> i32 {
    if as_json {
        let v = serde_json::json!({
            "schemaVersion": 1,
            "name": "ilo",
            "version": env!("CARGO_PKG_VERSION"),
            "features": features_list(),
        });
        match serde_json::to_string_pretty(&v) {
            Ok(s) => println!("{}", s),
            Err(e) => {
                eprintln!("error: failed to serialise version: {e}");
                return 1;
            }
        }
    } else {
        println!("ilo {}", env!("CARGO_PKG_VERSION"));
    }
    0
}

/// Build-time feature flags that affect runtime behaviour. Surfaced in the
/// `--json` version output so agents can detect e.g. whether the JIT or
/// MCP-tools feature is compiled in without having to probe with a sample
/// program.
fn features_list() -> Vec<&'static str> {
    // Each entry is wrapped in `Option` so the cfg gates collapse to `None`
    // when a feature is off without tripping `clippy::vec_init_then_push`.
    let entries: [Option<&'static str>; 3] = [
        #[cfg(feature = "cranelift")]
        Some("cranelift"),
        #[cfg(not(feature = "cranelift"))]
        None,
        #[cfg(feature = "llvm")]
        Some("llvm"),
        #[cfg(not(feature = "llvm"))]
        None,
        #[cfg(feature = "tools")]
        Some("tools"),
        #[cfg(not(feature = "tools"))]
        None,
    ];
    entries.into_iter().flatten().collect()
}

/// `ilo explain ILO-XXXX` — plain prints the long-form explanation,
/// `--json` emits a structured envelope with `code`, `short`, and `long`
/// so agent tooling can route on the error code class without parsing
/// markdown.
fn explain_cmd(code: &str, as_json: bool) -> i32 {
    match diagnostic::registry::lookup(code) {
        Some(entry) => {
            if as_json {
                let v = serde_json::json!({
                    "schemaVersion": 1,
                    "code": entry.code,
                    "phase": entry.phase.as_str(),
                    "short": entry.short,
                    "long": entry.long,
                });
                match serde_json::to_string_pretty(&v) {
                    Ok(s) => println!("{}", s),
                    Err(e) => {
                        eprintln!("error: failed to serialise explain: {e}");
                        return 1;
                    }
                }
            } else {
                print!("{}", entry.long);
            }
            0
        }
        None => {
            if as_json {
                let v = serde_json::json!({
                    "schemaVersion": 1,
                    "error": {
                        "code": "unknown-error-code",
                        "message": format!("unknown error code: {code}"),
                        "input": code,
                    }
                });
                println!("{}", v);
            } else {
                eprintln!("unknown error code: {}", code);
                eprintln!("Error codes have the form ILO-L001, ILO-P001, ILO-T001, ILO-R001.");
            }
            1
        }
    }
}

// ── `ilo tools` subcommand ─────────────────────────────────────────────────

#[derive(Clone, Copy, PartialEq, Eq)]
enum ToolsOutputFmt {
    Human, // human-readable table (default)
    Ilo,   // valid Decl::Tool ilo syntax
    Json,  // JSON array
}

/// Load and display tool signatures from MCP / HTTP sources.  Returns exit code.
fn tools_cmd(args: &[String]) -> i32 {
    let mut mcp_path: Option<String> = None;
    let mut http_path: Option<String> = None;
    let mut fmt = ToolsOutputFmt::Human;
    let mut full = false;
    let mut graph = false;

    let mut i = 0;
    while i < args.len() {
        match args[i].as_str() {
            "--mcp" | "-m" => {
                if i + 1 >= args.len() {
                    eprintln!("error: --mcp requires a path");
                    return 1;
                }
                mcp_path = Some(args[i + 1].clone());
                i += 2;
            }
            "--tools" | "-t" => {
                if i + 1 >= args.len() {
                    eprintln!("error: --tools requires a path");
                    return 1;
                }
                http_path = Some(args[i + 1].clone());
                i += 2;
            }
            "--human" => {
                fmt = ToolsOutputFmt::Human;
                i += 1;
            }
            "--ilo" => {
                fmt = ToolsOutputFmt::Ilo;
                i += 1;
            }
            "--json" => {
                fmt = ToolsOutputFmt::Json;
                i += 1;
            }
            "--full" | "-f" => {
                full = true;
                i += 1;
            }
            "--graph" | "-g" => {
                graph = true;
                i += 1;
            }
            _ => {
                eprintln!("unknown flag: {}", args[i]);
                eprintln!(
                    "Usage: ilo tools [-m <path>] [-t <path>] \
                     [--human|--ilo|--json] [--full] [--graph]"
                );
                return 1;
            }
        }
    }

    if mcp_path.is_none() && http_path.is_none() {
        eprintln!("error: ilo tools requires at least one of --mcp <path> or --tools <path>");
        eprintln!(
            "Usage: ilo tools [--mcp <path>] [--tools <path>] \
             [--human|--ilo|--json] [--full] [--graph]"
        );
        return 1;
    }

    // --ilo, --json, and --graph always show full signatures.
    if matches!(fmt, ToolsOutputFmt::Ilo | ToolsOutputFmt::Json) || graph {
        full = true;
    }

    // ── HTTP tools (sync, no feature gate) ───────────────────────────────────
    let mut http_names: Vec<String> = Vec::new();
    if let Some(ref path) = http_path {
        let config = match tools::http_provider::ToolsConfig::from_file(path) {
            Ok(c) => c,
            Err(e) => {
                eprintln!("{}", e);
                return 1;
            }
        };
        let mut names: Vec<String> = config.tools.keys().cloned().collect();
        names.sort();
        http_names = names;
    }

    // ── MCP tools (async, feature-gated) ─────────────────────────────────────
    let mcp_decls = match collect_mcp_tool_decls(mcp_path.as_deref()) {
        Ok(d) => d,
        Err(e) => {
            eprintln!("{}", e);
            return 1;
        }
    };

    // ── Render ────────────────────────────────────────────────────────────────
    match fmt {
        ToolsOutputFmt::Human => {
            for name in &http_names {
                if full {
                    println!("{:<32} (http tool — no type info)", name);
                } else {
                    println!("{}", name);
                }
            }
            for decl in &mcp_decls {
                if let ast::Decl::Tool {
                    name,
                    description,
                    params,
                    return_type,
                    ..
                } = decl
                {
                    if full {
                        let sig = tool_sig_str(params, return_type);
                        println!("{:<32} {:<44} {}", name, description, sig);
                    } else {
                        println!("{}", name);
                    }
                }
            }
        }
        ToolsOutputFmt::Ilo => {
            for name in &http_names {
                // No type info: emit with empty description and generic R t t.
                println!("tool {}\"\" > R t t", name);
            }
            for decl in &mcp_decls {
                println!(
                    "{}",
                    codegen::fmt::format_decl(decl, codegen::fmt::FmtMode::Dense)
                );
            }
        }
        ToolsOutputFmt::Json => {
            let mut items: Vec<serde_json::Value> = Vec::new();
            for name in &http_names {
                items.push(serde_json::json!({
                    "name": name,
                    "source": "http",
                    "description": null,
                    "params": [],
                    "return": null
                }));
            }
            for decl in &mcp_decls {
                if let ast::Decl::Tool {
                    name,
                    description,
                    params,
                    return_type,
                    ..
                } = decl
                {
                    let params_json: Vec<serde_json::Value> = params
                        .iter()
                        .map(|p| {
                            serde_json::json!({
                                "name": p.name,
                                "type": codegen::fmt::type_str(&p.ty)
                            })
                        })
                        .collect();
                    items.push(serde_json::json!({
                        "name": name,
                        "source": "mcp",
                        "description": description,
                        "params": params_json,
                        "return": codegen::fmt::type_str(return_type)
                    }));
                }
            }
            // Wrap the tool list in an object so `schemaVersion` can sit at
            // the top level. The legacy shape was a bare array; bringing it
            // into the 0.12.1 uniformity is a breaking change for consumers
            // that indexed `[0]` directly, but it lets agents route every
            // `--json` envelope on a single field.
            let envelope = serde_json::json!({
                "schemaVersion": 1,
                "tools": items,
            });
            match serde_json::to_string_pretty(&envelope) {
                Ok(s) => println!("{}", s),
                Err(e) => {
                    eprintln!("failed to render JSON: {}", e);
                    return 1;
                }
            }
        }
    }

    // ── Graph (additive — shown after or instead of table) ───────────────────
    if graph {
        print_tool_graph(&mcp_decls);
    }

    0
}

/// Print a type-level composition graph: for each tool, which tools can consume its output.
fn print_tool_graph(decls: &[ast::Decl]) {
    // Collect (name, params, return_type) for all typed tools.
    let tools: Vec<(&str, &[ast::Param], &ast::Type)> = decls
        .iter()
        .filter_map(|d| {
            if let ast::Decl::Tool {
                name,
                params,
                return_type,
                ..
            } = d
            {
                Some((name.as_str(), params.as_slice(), return_type))
            } else {
                None
            }
        })
        .collect();

    if tools.is_empty() {
        println!("(no typed tools — graph requires MCP source)");
        return;
    }

    // Name column width.
    let name_w = tools
        .iter()
        .map(|(n, _, _)| n.len())
        .max()
        .unwrap_or(8)
        .max(8);
    // Sig column width — cap at 36 for readability.
    let sig_w: usize = 36;

    println!("Tool composition graph\n");
    println!("{:<name_w$}  {:<sig_w$}  feeds →", "tool", "signature");
    println!("{}", "─".repeat(name_w + 2 + sig_w + 2 + 40));

    for &(src_name, src_params, src_ret) in &tools {
        let sig = tool_sig_str(src_params, src_ret);
        // The "output" is the ok branch of R, or the type itself.
        let out_ty = tool_ok_type(src_ret);

        // Find tools whose first param (or any param) accepts out_ty.
        let mut consumers: Vec<&str> = tools
            .iter()
            .filter(|&&(dst_name, dst_params, _)| {
                dst_name != src_name
                    && dst_params
                        .iter()
                        .any(|p| types_pipe_compatible(out_ty, &p.ty))
            })
            .map(|&(n, _, _)| n)
            .collect();
        consumers.sort();

        let feeds = if consumers.is_empty() {
            "—".to_string()
        } else {
            consumers.join(", ")
        };

        let sig_char_len = sig.chars().count();
        let sig_display = if sig_char_len > sig_w {
            let truncated: String = sig.chars().take(sig_w.saturating_sub(1)).collect();
            format!("{}…", truncated)
        } else {
            sig
        };
        println!("{:<name_w$}  {:<sig_w$}  {}", src_name, sig_display, feeds);
    }
    println!();
}

/// Unwrap `R ok err` → `ok`; otherwise return the type itself.
fn tool_ok_type(ty: &ast::Type) -> &ast::Type {
    if let ast::Type::Result(ok, _) = ty {
        ok
    } else {
        ty
    }
}

/// True if a value of type `out` can be piped into a parameter of type `param`.
/// Intentionally permissive: unknown/named types match anything.
fn types_pipe_compatible(out: &ast::Type, param: &ast::Type) -> bool {
    use ast::Type::*;
    // Unwrap Optional on the param side — Optional(T) accepts T.
    let param = if let Optional(inner) = param {
        inner
    } else {
        param
    };
    match (out, param) {
        // Named / unknown / Any types — treat as wildcard.
        (Named(_), _) | (_, Named(_)) | (Any, _) | (_, Any) => true,
        // Exact matches.
        (Number, Number) | (Text, Text) | (Bool, Bool) => true,
        // List element type must match.
        (List(a), List(b)) => types_pipe_compatible(a, b),
        // Map — key and value types must match.
        (Map(ak, av), Map(bk, bv)) => {
            types_pipe_compatible(ak, bk) && types_pipe_compatible(av, bv)
        }
        // Result ok branch feeds a result-accepting param.
        (Result(ao, ae), Result(bo, be)) => {
            types_pipe_compatible(ao, bo) && types_pipe_compatible(ae, be)
        }
        // Sum types are text at runtime — compatible with text params.
        (Sum(_), Text) | (Text, Sum(_)) | (Sum(_), Sum(_)) => true,
        _ => false,
    }
}

/// Format params + return type as a human-readable signature string.
fn tool_sig_str(params: &[ast::Param], ret: &ast::Type) -> String {
    let ps: Vec<String> = params
        .iter()
        .map(|p| format!("{}:{}", p.name, codegen::fmt::type_str(&p.ty)))
        .collect();
    if ps.is_empty() {
        format!("> {}", codegen::fmt::type_str(ret))
    } else {
        format!("{} > {}", ps.join(" "), codegen::fmt::type_str(ret))
    }
}

// ── `ilo graph` subcommand ────────────────────────────────────────────────

/// Analyze a program's dependency graph and output JSON / DOT.  Returns exit code.
fn graph_cmd(args: &[String]) -> i32 {
    if args.is_empty() {
        eprintln!(
            "Usage: ilo graph <file> [--fn NAME] [--reverse] [--subgraph] [--budget N] [--dot]"
        );
        return 1;
    }

    let file = &args[0];
    let source = match std::fs::read_to_string(file) {
        Ok(s) => s,
        Err(e) => {
            eprintln!("Error reading {}: {}", file, e);
            return 1;
        }
    };

    let tokens = match lexer::lex(&source) {
        Ok(t) => t,
        Err(e) => {
            eprintln!("Lex error: {:?}", e);
            return 1;
        }
    };
    let token_spans: Vec<(lexer::Token, ast::Span)> = tokens
        .into_iter()
        .map(|(t, r)| {
            (
                t,
                ast::Span {
                    start: r.start,
                    end: r.end,
                },
            )
        })
        .collect();
    let (mut program, _) = parser::parse(token_spans);
    ast::resolve_aliases(&mut program);
    ast::desugar_dot_var_index(&mut program);
    program.source = Some(source);

    let pg = graph::build_graph(&program);

    // Parse flags.
    let mut fn_name: Option<String> = None;
    let mut reverse = false;
    let mut subgraph = false;
    let mut budget: Option<usize> = None;
    let mut dot = false;

    let mut i = 1;
    while i < args.len() {
        match args[i].as_str() {
            "--fn" => {
                if i + 1 >= args.len() {
                    eprintln!("error: --fn requires a function name");
                    return 1;
                }
                fn_name = Some(args[i + 1].clone());
                i += 2;
            }
            "--reverse" => {
                reverse = true;
                i += 1;
            }
            "--subgraph" => {
                subgraph = true;
                i += 1;
            }
            "--budget" => {
                if i + 1 >= args.len() {
                    eprintln!("error: --budget requires a number");
                    return 1;
                }
                match args[i + 1].parse::<usize>() {
                    Ok(v) => budget = Some(v),
                    Err(_) => {
                        eprintln!("error: --budget value must be a positive integer");
                        return 1;
                    }
                }
                i += 2;
            }
            "--dot" => {
                dot = true;
                i += 1;
            }
            _ => {
                eprintln!("unknown flag: {}", args[i]);
                return 1;
            }
        }
    }

    if dot {
        print!("{}", graph::to_dot(&pg));
        return 0;
    }

    // Emit a graph payload with `schemaVersion: 1` injected at the top level.
    // Graph queries serialise to JSON objects with disjoint key sets from
    // `schemaVersion`, so flattening is strictly additive: old consumers that
    // ignore the new field keep working, new consumers can route on it.
    fn emit_with_schema_version<T: serde::Serialize>(payload: &T) -> i32 {
        let mut v = match serde_json::to_value(payload) {
            Ok(v) => v,
            Err(e) => {
                eprintln!("error serialising graph: {}", e);
                return 1;
            }
        };
        if let Some(obj) = v.as_object_mut() {
            obj.insert(
                "schemaVersion".to_string(),
                serde_json::Value::Number(1.into()),
            );
        }
        match serde_json::to_string_pretty(&v) {
            Ok(s) => {
                println!("{}", s);
                0
            }
            Err(e) => {
                eprintln!("error serialising graph: {}", e);
                1
            }
        }
    }

    if let Some(ref name) = fn_name {
        if reverse {
            match graph::query_reverse(&program, &pg, name) {
                Some(r) => emit_with_schema_version(&r),
                None => {
                    eprintln!("function '{}' not found", name);
                    1
                }
            }
        } else if let Some(b) = budget {
            match graph::query_budget(&program, &pg, name, b) {
                Some(q) => emit_with_schema_version(&q),
                None => {
                    eprintln!("function '{}' not found", name);
                    1
                }
            }
        } else if subgraph {
            match graph::query_subgraph(&program, &pg, name) {
                Some(q) => emit_with_schema_version(&q),
                None => {
                    eprintln!("function '{}' not found", name);
                    1
                }
            }
        } else {
            match graph::query_fn(&program, &pg, name) {
                Some(q) => emit_with_schema_version(&q),
                None => {
                    eprintln!("function '{}' not found", name);
                    1
                }
            }
        }
    } else {
        // Full graph output.
        emit_with_schema_version(&pg)
    }
}

/// Connect to MCP servers and return synthesized `Decl::Tool` nodes.
/// Returns `Err(message)` on failure.
#[cfg(feature = "tools")]
fn collect_mcp_tool_decls(path: Option<&str>) -> Result<Vec<ast::Decl>, String> {
    let path = match path {
        Some(p) => p,
        None => return Ok(vec![]),
    };
    let config = tools::mcp_provider::McpConfig::from_file(path).map_err(|e| e.to_string())?;
    let rt = tokio::runtime::Builder::new_current_thread()
        .enable_all()
        .build()
        .expect("tokio runtime");
    let provider = rt
        .block_on(tools::mcp_provider::McpProvider::connect(&config))
        .map_err(|e| format!("MCP error: {}", e))?;
    Ok(provider.tool_decls())
}

#[cfg(not(feature = "tools"))]
fn collect_mcp_tool_decls(path: Option<&str>) -> Result<Vec<ast::Decl>, String> {
    if path.is_some() {
        return Err("error: --mcp requires the 'tools' feature \
             (build with: cargo build --features tools)"
            .to_string());
    }
    Ok(vec![])
}

// ── `ilo httpd` subcommand ────────────────────────────────────────────────────
//
// Serves HTTP requests by calling a user-defined ilo handler function.
//
// Handler signature (ilo source):
//   type Request{method:t;path:t;headers:M t t;body:t}
//   type Response{status:n;headers:M t t;body:t}
//   handler req:Request>Response; ...
//
// One thread is spawned per accepted connection (minimal thread-per-request
// pool). No async runtime is required — the ilo interpreter is synchronous.
//
// TODO(ILO-59): add --allow-net cap check once the cap-flags PR lands.

fn httpd_cmd(port: u16, handler_file: &str, func_name: &str) -> i32 {
    use std::net::TcpListener;
    use std::sync::Arc;

    // ── Load and compile the handler program once ─────────────────────────────
    let source = match std::fs::read_to_string(handler_file) {
        Ok(s) => s,
        Err(e) => {
            eprintln!("error: cannot read handler file '{}': {}", handler_file, e);
            return 1;
        }
    };

    let tokens = match lexer::lex(&source) {
        Ok(t) => t,
        Err(e) => {
            let d = Diagnostic::from(&e).with_source(source.clone());
            eprint!("{}", AnsiRenderer { use_color: true }.render(&d));
            return 1;
        }
    };
    let token_spans: Vec<_> = tokens
        .into_iter()
        .map(|(t, r)| {
            (
                t,
                ast::Span {
                    start: r.start,
                    end: r.end,
                },
            )
        })
        .collect();

    let (mut program, parse_errors) = parser::parse(token_spans);
    ast::resolve_aliases(&mut program);
    ast::desugar_dot_var_index(&mut program);
    program.source = Some(source.clone());

    if !parse_errors.is_empty() {
        for e in &parse_errors {
            let d = Diagnostic::from(e).with_source(source.clone());
            eprint!("{}", AnsiRenderer { use_color: true }.render(&d));
        }
        return 1;
    }

    let vr = verify::verify(&program);
    for w in &vr.warnings {
        eprint!(
            "{}",
            AnsiRenderer { use_color: true }
                .render(&Diagnostic::from(w).with_source(source.clone()))
        );
    }
    if !vr.errors.is_empty() {
        for e in &vr.errors {
            eprint!(
                "{}",
                AnsiRenderer { use_color: true }
                    .render(&Diagnostic::from(e).with_source(source.clone()))
            );
        }
        return 1;
    }

    let program = Arc::new(program);
    let func = func_name.to_string();

    // ── Bind the TCP listener ─────────────────────────────────────────────────
    let addr = format!("0.0.0.0:{}", port);
    let listener = match TcpListener::bind(&addr) {
        Ok(l) => l,
        Err(e) => {
            eprintln!("error: cannot bind to {}: {}", addr, e);
            return 1;
        }
    };
    eprintln!("ilo httpd listening on http://0.0.0.0:{}", port);

    // ── Accept loop: one thread per connection ────────────────────────────────
    for stream in listener.incoming() {
        let stream = match stream {
            Ok(s) => s,
            Err(e) => {
                eprintln!("accept error: {}", e);
                continue;
            }
        };
        let program = Arc::clone(&program);
        let func = func.clone();

        std::thread::spawn(move || {
            if let Err(e) = handle_http_connection(stream, &program, &func) {
                eprintln!("connection error: {}", e);
            }
        });
    }
    0
}

/// Parse one HTTP/1.1 request from `stream`, call the ilo handler, write the response.
fn handle_http_connection(
    stream: std::net::TcpStream,
    program: &ast::Program,
    func_name: &str,
) -> Result<(), Box<dyn std::error::Error>> {
    use std::collections::HashMap;
    use std::io::{BufRead, BufReader, Write};

    let peer = stream
        .peer_addr()
        .map(|a| a.to_string())
        .unwrap_or_default();
    let mut reader = BufReader::new(stream.try_clone()?);
    let mut writer = stream;

    // ── Parse request line ────────────────────────────────────────────────────
    let mut request_line = String::new();
    reader.read_line(&mut request_line)?;
    let request_line = request_line.trim_end();

    let mut parts = request_line.splitn(3, ' ');
    let method = parts.next().unwrap_or("GET").to_string();
    let path = parts.next().unwrap_or("/").to_string();
    // HTTP version ignored for simplicity.

    // ── Parse headers ─────────────────────────────────────────────────────────
    let mut raw_headers: Vec<(String, String)> = Vec::new();
    let mut content_length: usize = 0;
    loop {
        let mut line = String::new();
        reader.read_line(&mut line)?;
        let line = line.trim_end();
        if line.is_empty() {
            break;
        }
        if let Some((k, v)) = line.split_once(':') {
            let key = k.trim().to_lowercase();
            let val = v.trim().to_string();
            if key == "content-length" {
                content_length = val.parse().unwrap_or(0);
            }
            raw_headers.push((key, val));
        }
    }

    // ── Read body ─────────────────────────────────────────────────────────────
    let body = if content_length > 0 {
        let mut buf = vec![0u8; content_length];
        use std::io::Read;
        reader.read_exact(&mut buf)?;
        String::from_utf8_lossy(&buf).into_owned()
    } else {
        String::new()
    };

    // ── Build ilo Request record ───────────────────────────────────────────────
    use interpreter::MapKey;
    use interpreter::Value;

    let mut hdr_map: HashMap<interpreter::MapKey, Value> = HashMap::new();
    for (k, v) in &raw_headers {
        hdr_map.insert(
            MapKey::Text(k.clone()),
            Value::Text(std::sync::Arc::new(v.clone())),
        );
    }

    let mut req_fields: HashMap<String, Value> = HashMap::new();
    req_fields.insert(
        "method".to_string(),
        Value::Text(std::sync::Arc::new(method.clone())),
    );
    req_fields.insert(
        "path".to_string(),
        Value::Text(std::sync::Arc::new(path.clone())),
    );
    req_fields.insert(
        "headers".to_string(),
        Value::Map(std::sync::Arc::new(hdr_map)),
    );
    req_fields.insert("body".to_string(), Value::Text(std::sync::Arc::new(body)));

    let req_val = Value::Record {
        type_name: "Request".to_string(),
        fields: req_fields,
    };

    // ── Call handler ──────────────────────────────────────────────────────────
    let result = interpreter::run(program, Some(func_name), vec![req_val]);

    // ── Extract Response record ───────────────────────────────────────────────
    let resp = match result {
        Ok(v) => v,
        Err(e) => {
            let msg = format!("handler error: {}", e);
            eprintln!("{}", msg);
            let body = format!("Internal Server Error: {}\n", e);
            let resp_bytes = format!(
                "HTTP/1.1 500 Internal Server Error\r\nContent-Type: text/plain\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{}",
                body.len(),
                body
            );
            writer.write_all(resp_bytes.as_bytes())?;
            eprintln!("{} {} {} -> 500", peer, method, path);
            return Ok(());
        }
    };

    // Unwrap Result wrappers (handler may return R Response t)
    let resp = match resp {
        Value::Ok(inner) => *inner,
        Value::Err(e) => {
            let body = format!("Handler returned Err: {}\n", e);
            let resp_bytes = format!(
                "HTTP/1.1 500 Internal Server Error\r\nContent-Type: text/plain\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{}",
                body.len(),
                body
            );
            writer.write_all(resp_bytes.as_bytes())?;
            eprintln!("{} {} {} -> 500 (Err)", peer, method, path);
            return Ok(());
        }
        other => other,
    };

    // Body shape: either a plain string or a list of chunks for chunked transfer.
    enum BodyShape {
        Plain(String),
        Chunked(Vec<String>),
    }

    let (status, resp_headers, body_shape) = match &resp {
        Value::Record { fields, .. } => {
            let status = match fields.get("status") {
                Some(Value::Number(n)) => *n as u16,
                _ => 200,
            };
            // body may be:
            //   Text   → plain body (existing behaviour)
            //   List   → chunked: each element is a chunk
            //   FnRef/Closure → call it (no args) expecting a List, then chunk
            let body_shape = match fields.get("body") {
                Some(Value::Text(s)) => BodyShape::Plain((**s).clone()),
                Some(Value::List(items)) => {
                    let chunks = items.iter().map(|v| v.to_string()).collect();
                    BodyShape::Chunked(chunks)
                }
                Some(Value::FnRef(name)) => {
                    match interpreter::run(program, Some(name.as_str()), vec![]) {
                        Ok(Value::List(items)) => {
                            let chunks = items.iter().map(|v| v.to_string()).collect();
                            BodyShape::Chunked(chunks)
                        }
                        Ok(other) => BodyShape::Plain(other.to_string()),
                        Err(e) => BodyShape::Plain(format!("chunk-fn error: {}", e)),
                    }
                }
                Some(Value::Closure { fn_name, .. }) => {
                    match interpreter::run(program, Some(fn_name.as_str()), vec![]) {
                        Ok(Value::List(items)) => {
                            let chunks = items.iter().map(|v| v.to_string()).collect();
                            BodyShape::Chunked(chunks)
                        }
                        Ok(other) => BodyShape::Plain(other.to_string()),
                        Err(e) => BodyShape::Plain(format!("chunk-fn error: {}", e)),
                    }
                }
                Some(other) => BodyShape::Plain(other.to_string()),
                None => BodyShape::Plain(String::new()),
            };
            let resp_headers: Vec<(String, String)> = match fields.get("headers") {
                Some(Value::Map(m)) => m
                    .iter()
                    .map(|(k, v)| {
                        let ks = match k {
                            MapKey::Text(s) => s.clone(),
                            MapKey::Int(n) => n.to_string(),
                        };
                        let vs = match v {
                            Value::Text(s) => (**s).clone(),
                            other => other.to_string(),
                        };
                        (ks, vs)
                    })
                    .collect(),
                _ => vec![],
            };
            (status, resp_headers, body_shape)
        }
        // Handler returned bare text — wrap as 200 OK text/plain
        Value::Text(s) => (200u16, vec![], BodyShape::Plain((**s).clone())),
        other => (200u16, vec![], BodyShape::Plain(other.to_string())),
    };

    let status_text = match status {
        200 => "OK",
        201 => "Created",
        204 => "No Content",
        400 => "Bad Request",
        401 => "Unauthorized",
        403 => "Forbidden",
        404 => "Not Found",
        500 => "Internal Server Error",
        _ => "OK",
    };

    let has_content_type = resp_headers
        .iter()
        .any(|(k, _)| k.to_lowercase() == "content-type");

    match body_shape {
        BodyShape::Plain(resp_body) => {
            let mut header_block = format!("HTTP/1.1 {} {}\r\n", status, status_text);
            if !has_content_type {
                header_block.push_str("Content-Type: text/plain; charset=utf-8\r\n");
            }
            for (k, v) in &resp_headers {
                header_block.push_str(&format!("{}: {}\r\n", k, v));
            }
            header_block.push_str(&format!("Content-Length: {}\r\n", resp_body.len()));
            header_block.push_str("Connection: close\r\n");
            header_block.push_str("\r\n");
            writer.write_all(header_block.as_bytes())?;
            writer.write_all(resp_body.as_bytes())?;
        }
        BodyShape::Chunked(chunks) => {
            // RFC 7230 §4.1 chunked transfer encoding.
            let mut header_block = format!("HTTP/1.1 {} {}\r\n", status, status_text);
            if !has_content_type {
                header_block.push_str("Content-Type: text/plain; charset=utf-8\r\n");
            }
            for (k, v) in &resp_headers {
                header_block.push_str(&format!("{}: {}\r\n", k, v));
            }
            header_block.push_str("Transfer-Encoding: chunked\r\n");
            header_block.push_str("Connection: close\r\n");
            header_block.push_str("\r\n");
            writer.write_all(header_block.as_bytes())?;
            for chunk in &chunks {
                let data = chunk.as_bytes();
                if !data.is_empty() {
                    writer.write_all(format!("{:x}\r\n", data.len()).as_bytes())?;
                    writer.write_all(data)?;
                    writer.write_all(b"\r\n")?;
                }
            }
            // Terminating chunk
            writer.write_all(b"0\r\n\r\n")?;
        }
    }

    eprintln!("{} {} {} -> {}", peer, method, path, status);
    Ok(())
}

// ── `ilo serv` subcommand ──────────────────────────────────────────────────

/// Render a `Diagnostic` as a `serde_json::Value` for inclusion in serve responses.
fn diag_to_json(d: &Diagnostic) -> serde_json::Value {
    let s = diagnostic::json::render(d);
    serde_json::from_str(&s).unwrap_or(serde_json::json!({"message": s}))
}

/// Process a single serve request line and return the JSON response.
fn process_serv_request(
    line: &str,
    mcp_tool_decls: &[ast::Decl],
    #[cfg(feature = "tools")] provider: Option<std::sync::Arc<dyn tools::ToolProvider>>,
    #[cfg_attr(not(feature = "tools"), allow(unused_variables))] http_config: Option<
        &tools::http_provider::ToolsConfig,
    >,
    #[cfg(feature = "tools")] rt: std::sync::Arc<tokio::runtime::Runtime>,
) -> serde_json::Value {
    #[derive(serde::Deserialize)]
    struct Req {
        program: String,
        #[serde(default)]
        args: Vec<String>,
        func: Option<String>,
    }

    let req: Req = match serde_json::from_str(line) {
        Ok(r) => r,
        Err(e) => {
            return serde_json::json!({
                "schemaVersion": 1,
                "error": {"phase": "request", "message": format!("invalid JSON: {e}")}
            });
        }
    };

    let start = std::time::Instant::now();
    let source = req.program.clone();

    // Lex
    let tokens = match lexer::lex(&source) {
        Ok(t) => t,
        Err(e) => {
            return serde_json::json!({
                "schemaVersion": 1,
                "error": {
                    "phase": "lex",
                    "diagnostics": [diag_to_json(&Diagnostic::from(&e))]
                }
            });
        }
    };

    // Parse
    let token_spans: Vec<_> = tokens
        .into_iter()
        .map(|(t, r)| {
            (
                t,
                ast::Span {
                    start: r.start,
                    end: r.end,
                },
            )
        })
        .collect();
    let (mut program, parse_errors) = parser::parse(token_spans);
    ast::resolve_aliases(&mut program);
    ast::desugar_dot_var_index(&mut program);
    program.source = Some(source.clone());

    if !parse_errors.is_empty() {
        let diags: Vec<_> = parse_errors
            .iter()
            .map(|e| diag_to_json(&Diagnostic::from(e)))
            .collect();
        return serde_json::json!({"schemaVersion": 1, "error": {"phase": "parse", "diagnostics": diags}});
    }

    // Inject static MCP tool decls so the verifier sees them
    if !mcp_tool_decls.is_empty() {
        let mut decls = mcp_tool_decls.to_vec();
        decls.append(&mut program.declarations);
        program.declarations = decls;
    }

    // Verify
    let vr = verify::verify(&program);
    if !vr.errors.is_empty() {
        let diags: Vec<_> = vr
            .errors
            .iter()
            .map(|e| diag_to_json(&Diagnostic::from(e).with_source(source.clone())))
            .collect();
        return serde_json::json!({"schemaVersion": 1, "error": {"phase": "verify", "diagnostics": diags}});
    }

    // Compile to VM bytecode (PR E of ILO-45: tree-walker engine removed).
    let compiled = match vm::compile(&program) {
        Ok(c) => c,
        Err(e) => {
            let d = Diagnostic::from(&e).with_source(source);
            return serde_json::json!({"schemaVersion": 1, "error": {"phase": "compile", "diagnostics": [diag_to_json(&d)]}});
        }
    };

    // Run
    let func_name = req.func.as_deref();
    let run_args = parse_cli_args_typed(&program, func_name, &req.args);

    #[cfg(feature = "tools")]
    let result = if let Some(p) = provider {
        vm::run_with_tools(&compiled, func_name, run_args, &*p, &*rt)
    } else if let Some(cfg) = http_config {
        let p = tools::http_provider::HttpProvider::new(cfg.clone());
        vm::run_with_tools(&compiled, func_name, run_args, &p, &*rt)
    } else {
        vm::run(&compiled, func_name, run_args)
    };

    #[cfg(not(feature = "tools"))]
    let result = vm::run(&compiled, func_name, run_args);

    let ms = start.elapsed().as_millis() as u64;

    match result {
        Ok(value) => match value {
            runtime::Value::Ok(inner) => {
                let v = inner.to_json().unwrap_or(serde_json::Value::Null);
                serde_json::json!({"schemaVersion": 1, "ok": v, "ms": ms})
            }
            runtime::Value::Err(inner) => {
                let v = inner
                    .to_json()
                    .unwrap_or_else(|_| serde_json::Value::String(inner.to_string()));
                serde_json::json!({"schemaVersion": 1, "error": {"phase": "program", "value": v}, "ms": ms})
            }
            other => {
                let v = other
                    .to_json()
                    .unwrap_or_else(|_| serde_json::Value::String(other.to_string()));
                serde_json::json!({"schemaVersion": 1, "ok": v, "ms": ms})
            }
        },
        Err(e) => {
            let d = Diagnostic::from(&e).with_source(source);
            serde_json::json!({"schemaVersion": 1, "error": {"phase": "runtime", "diagnostics": [diag_to_json(&d)]}})
        }
    }
}

fn type_to_ilo(ty: &ast::Type) -> String {
    match ty {
        ast::Type::Number => "n".to_string(),
        ast::Type::Text => "t".to_string(),
        ast::Type::Bool => "b".to_string(),
        ast::Type::Any => "_".to_string(),
        ast::Type::Optional(inner) => format!("O {}", type_to_ilo(inner)),
        ast::Type::List(inner) => format!("L {}", type_to_ilo(inner)),
        ast::Type::Map(k, v) => format!("M {} {}", type_to_ilo(k), type_to_ilo(v)),
        ast::Type::Result(ok, err) => format!("R {} {}", type_to_ilo(ok), type_to_ilo(err)),
        ast::Type::Sum(variants) => format!("S {}", variants.join(" ")),
        ast::Type::Fn(params, ret) => {
            let ps: Vec<_> = params.iter().map(type_to_ilo).collect();
            format!("F {} {}", ps.join(" "), type_to_ilo(ret))
        }
        ast::Type::Named(name) => name.clone(),
        ast::Type::U32 => "U32".to_string(),
        ast::Type::U64 => "U64".to_string(),
        ast::Type::I64 => "I64".to_string(),
    }
}

/// Count brace depth: returns >0 if there are unclosed `{` braces.
/// Ignores braces inside string literals and comments.
fn brace_depth(s: &str) -> i32 {
    let mut depth: i32 = 0;
    let mut in_string = false;
    let mut prev_backslash = false;
    let mut chars = s.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '-' && chars.peek() == Some(&'-') && !in_string {
            break; // `--` comment runs to end of input
        }
        if c == '"' {
            if in_string && prev_backslash {
                // Escaped quote inside string — don't toggle
                prev_backslash = false;
                continue;
            }
            in_string = !in_string;
            prev_backslash = false;
            continue;
        }
        if in_string {
            // Track backslashes: `\\` cancels out, so only odd runs count
            prev_backslash = c == '\\' && !prev_backslash;
            continue;
        }
        prev_backslash = false;
        if c == '{' {
            depth += 1;
        } else if c == '}' {
            depth -= 1;
        }
    }
    depth
}

/// Interactive REPL — define functions, evaluate expressions, accumulate state.
fn repl_cmd() {
    use std::io::{BufRead, Write};

    let version = env!("CARGO_PKG_VERSION");
    let renderer = AnsiRenderer { use_color: true };
    println!("ilo {version} — type :help for commands, :q to quit\n");

    // Accumulated function definitions across the session
    let mut defs: Vec<String> = Vec::new();

    let stdin = std::io::stdin();
    let mut reader = stdin.lock();

    loop {
        print!("> ");
        std::io::stdout().flush().ok();

        let mut line = String::new();
        match reader.read_line(&mut line) {
            Ok(0) => break, // Ctrl+D / EOF
            Ok(_) => {}
            Err(_) => break,
        }

        let mut input_buf = line.trim().to_string();
        if input_buf.is_empty() {
            continue;
        }

        // Multi-line: keep reading if braces are unbalanced or line ends with `;`
        while brace_depth(&input_buf) > 0 || input_buf.ends_with(';') {
            print!(".. ");
            std::io::stdout().flush().ok();
            let mut cont = String::new();
            match reader.read_line(&mut cont) {
                Ok(0) => break, // Ctrl+D
                Ok(_) => {}
                Err(_) => break,
            }
            let trimmed = cont.trim();
            if trimmed.is_empty() {
                break; // blank line submits what we have
            }
            // Join with `;` so multi-line fields/statements parse correctly,
            // but not when: buffer already ends with `;`, after `{`, or before `}`
            if !input_buf.ends_with('{') && !input_buf.ends_with(';') && !trimmed.starts_with('}') {
                input_buf.push(';');
            }
            input_buf.push_str(trimmed);
        }

        let input = input_buf.trim();
        if input.is_empty() {
            continue;
        }

        // Meta-commands (nvim-style)
        if input.starts_with(':') {
            match input {
                ":q" | ":q!" | ":x" | ":quit" | ":exit" => break,
                ":wq" => {
                    if defs.is_empty() {
                        eprintln!("no definitions to save");
                    } else {
                        eprintln!("usage: :w <file.@>");
                    }
                    continue;
                }
                _ if input.starts_with(":wq ") || input.starts_with(":w ") => {
                    let is_wq = input.starts_with(":wq");
                    let path = match input.split_once(' ') {
                        Some((_, p)) => p.trim(),
                        None => {
                            eprintln!("usage: :w <file.@>");
                            continue;
                        }
                    };
                    if defs.is_empty() {
                        eprintln!("no definitions to save");
                    } else if let Err(e) = std::fs::write(path, defs.join(" ") + "\n") {
                        eprintln!("error: {e}");
                    } else {
                        println!("saved {} definition(s) to {path}", defs.len());
                    }
                    if is_wq {
                        break;
                    } else {
                        continue;
                    }
                }
                ":defs" => {
                    if defs.is_empty() {
                        println!("(no definitions)");
                    } else {
                        for d in &defs {
                            println!("  {d}");
                        }
                    }
                    continue;
                }
                ":clear" => {
                    defs.clear();
                    println!("cleared all definitions");
                    continue;
                }
                ":help" => {
                    println!(":q :q! :x :quit :exit   quit");
                    println!(":w <file>               save definitions to file");
                    println!(":wq <file>              save and quit");
                    println!(":defs                   list defined functions");
                    println!(":clear                  clear all definitions");
                    println!(":help                   show this help");
                    continue;
                }
                _ => {
                    eprintln!("unknown command: {input}  (type :help)");
                    continue;
                }
            }
        }

        // Also support bare "exit"
        if input == "exit" || input == "quit" {
            break;
        }

        // Try to parse input as function definition(s) first
        let def_program = {
            let tokens = lexer::lex(input);
            if let Ok(tokens) = tokens {
                let token_spans: Vec<_> = tokens
                    .into_iter()
                    .map(|(t, r)| {
                        (
                            t,
                            ast::Span {
                                start: r.start,
                                end: r.end,
                            },
                        )
                    })
                    .collect();
                let (program, errors) = parser::parse(token_spans);
                if errors.is_empty()
                    && !program.declarations.is_empty()
                    && program.declarations.iter().all(|d| {
                        matches!(
                            d,
                            ast::Decl::Function { .. }
                                | ast::Decl::TypeDef { .. }
                                | ast::Decl::Alias { .. }
                        )
                    })
                {
                    Some(program)
                } else {
                    None
                }
            } else {
                None
            }
        };

        if let Some(program) = def_program {
            defs.push(input.to_string());

            for d in &program.declarations {
                match d {
                    ast::Decl::Function {
                        name,
                        params,
                        return_type,
                        ..
                    } => {
                        let params_str: Vec<_> = params
                            .iter()
                            .map(|p| format!("{}:{}", p.name, type_to_ilo(&p.ty)))
                            .collect();
                        println!(
                            "defined: {}({}) -> {}",
                            name,
                            params_str.join(", "),
                            type_to_ilo(return_type)
                        );
                    }
                    ast::Decl::TypeDef { name, fields, .. } => {
                        let fields_str: Vec<_> = fields
                            .iter()
                            .map(|f| format!("{}:{}", f.name, type_to_ilo(&f.ty)))
                            .collect();
                        println!("defined type: {}{{{}}}", name, fields_str.join(";"));
                    }
                    ast::Decl::Alias { name, target, .. } => {
                        println!("defined alias: {} = {}", name, type_to_ilo(target));
                    }
                    _ => {}
                }
            }
            continue;
        }

        // Expression or function call — wrap in a repl function with all accumulated defs
        // Use `repleval` as name (starts with letter, won't collide)
        let full_source = if defs.is_empty() {
            format!("repleval>n;{input}")
        } else {
            format!("{} repleval>n;{input}", defs.join(" "))
        };

        let tokens = match lexer::lex(&full_source) {
            Ok(t) => t,
            Err(e) => {
                let d = Diagnostic::from(&e);
                eprintln!("{}", renderer.render(&d));
                continue;
            }
        };

        let token_spans: Vec<_> = tokens
            .into_iter()
            .map(|(t, r)| {
                (
                    t,
                    ast::Span {
                        start: r.start,
                        end: r.end,
                    },
                )
            })
            .collect();
        let (mut full_program, parse_errors) = parser::parse(token_spans);
        ast::resolve_aliases(&mut full_program);
        ast::desugar_dot_var_index(&mut full_program);
        full_program.source = Some(full_source.clone());

        if !parse_errors.is_empty() {
            // Show errors relative to user input, not the wrapper
            for e in &parse_errors {
                let d = Diagnostic::from(e);
                eprintln!("{}", renderer.render(&d));
            }
            continue;
        }

        // Skip type checking for the repl wrapper — just compile and run on VM.
        // (PR E of ILO-45: tree-walker engine removed.)
        let compiled = match vm::compile(&full_program) {
            Ok(c) => c,
            Err(e) => {
                let d = Diagnostic::from(&e).with_source(full_source);
                eprintln!("{}", renderer.render(&d));
                continue;
            }
        };
        match vm::run(&compiled, Some("repleval"), vec![]) {
            Ok(value) => println!("{value}"),
            Err(e) => {
                let d = Diagnostic::from(&e).with_source(full_source);
                eprintln!("{}", renderer.render(&d));
            }
        }
    }
}

/// AOT compile an ilo program to a standalone native binary.  Returns exit code.
#[cfg(feature = "cranelift")]
fn compile_cmd(args: &[String]) -> i32 {
    if args.is_empty() {
        print_build_help();
        return 1;
    }

    if args.iter().any(|a| a == "--help" || a == "-h") {
        print_build_help();
        return 0;
    }

    let mut output_path: Option<String> = None;
    let mut source_arg: Option<&str> = None;
    let mut func_name: Option<&str> = None;
    let mut bench_mode = false;
    let mut as_json = false;
    let mut python_mode = false;
    let mut wasm_mode = false;
    let mut wasm_target_arg: Option<String> = None;
    let mut zero_mode = false;
    let mut zero_bin_mode = false;
    let mut i = 0;
    while i < args.len() {
        match args[i].as_str() {
            "-o" => {
                i += 1;
                if i >= args.len() {
                    eprintln!("Error: -o requires a path argument");
                    return 1;
                }
                output_path = Some(args[i].clone());
            }
            "--bench" => {
                bench_mode = true;
            }
            "--json" | "-j" => {
                as_json = true;
            }
            "--py" => {
                python_mode = true;
            }
            "--wasm" => {
                wasm_mode = true;
            }
            "--0" => {
                zero_mode = true;
            }
            "--0bin" => {
                zero_bin_mode = true;
            }
            "--target" => {
                i += 1;
                if i >= args.len() {
                    eprintln!("Error: --target requires a target name (e.g. wasm32-component)");
                    return 1;
                }
                wasm_target_arg = Some(args[i].clone());
            }
            _ if source_arg.is_none() => {
                source_arg = Some(&args[i]);
            }
            _ => {
                func_name = Some(&args[i]);
            }
        }
        i += 1;
    }

    if python_mode && bench_mode {
        eprintln!("Error: --py and --bench are mutually exclusive");
        return 1;
    }
    if wasm_mode && (python_mode || bench_mode) {
        eprintln!("Error: --wasm is mutually exclusive with --py / --bench");
        return 1;
    }
    if wasm_target_arg.is_some() && !wasm_mode {
        eprintln!("Error: --target only applies to --wasm builds");
        return 1;
    }
    if zero_mode && zero_bin_mode {
        eprintln!("Error: --0 and --0bin are mutually exclusive (--0bin already emits the source)");
        return 1;
    }
    if (zero_mode || zero_bin_mode) && (python_mode || wasm_mode || bench_mode) {
        eprintln!("Error: --0/--0bin is mutually exclusive with --py / --wasm / --bench");
        return 1;
    }

    let source_arg = match source_arg {
        Some(s) => s,
        None => {
            eprintln!("Error: no source file or code provided");
            return 1;
        }
    };

    // Read source from file or treat as inline code
    let source = if std::path::Path::new(source_arg).is_file() {
        maybe_warn_ilo_ext(source_arg);
        match std::fs::read_to_string(source_arg) {
            Ok(s) => s,
            Err(e) => {
                eprintln!("Error reading {}: {}", source_arg, e);
                return 1;
            }
        }
    } else {
        source_arg.to_string()
    };

    // Default output path: strip .ilo extension or use "a.out". With `--py`,
    // the default is `<basename>.py` so `ilo build foo.ilo --py` writes
    // `foo.py` next to the source.
    let output = output_path.unwrap_or_else(|| {
        if python_mode {
            if source_arg.ends_with(".ilo") {
                format!("{}.py", source_arg.trim_end_matches(".ilo"))
            } else {
                "out.py".to_string()
            }
        } else if wasm_mode {
            if source_arg.ends_with(".ilo") {
                format!("{}.wasm", source_arg.trim_end_matches(".ilo"))
            } else {
                "out.wasm".to_string()
            }
        } else if zero_mode {
            if source_arg.ends_with(".ilo") {
                format!("{}.0", source_arg.trim_end_matches(".ilo"))
            } else {
                "out.0".to_string()
            }
        } else if zero_bin_mode {
            if source_arg.ends_with(".ilo") {
                source_arg.trim_end_matches(".ilo").to_string()
            } else {
                "a.out".to_string()
            }
        } else if source_arg.ends_with(".ilo") {
            source_arg.trim_end_matches(".ilo").to_string()
        } else if source_arg.ends_with(".@") {
            source_arg.trim_end_matches(".@").to_string()
        } else {
            "a.out".to_string()
        }
    });

    // Lex
    let tokens = match lexer::lex(&source) {
        Ok(t) => t,
        Err(e) => {
            eprint!(
                "{}",
                AnsiRenderer { use_color: true }
                    .render(&Diagnostic::from(&e).with_source(source.clone()),)
            );
            return 1;
        }
    };
    let token_spans: Vec<(lexer::Token, ast::Span)> = tokens
        .into_iter()
        .map(|(t, r)| {
            (
                t,
                ast::Span {
                    start: r.start,
                    end: r.end,
                },
            )
        })
        .collect();

    // Parse
    let (mut program, parse_errors) = parser::parse(token_spans);
    if !parse_errors.is_empty() {
        for e in &parse_errors {
            let d = Diagnostic::from(e).with_source(source.clone());
            eprint!("{}", AnsiRenderer { use_color: true }.render(&d));
        }
        return 1;
    }
    ast::desugar_dot_var_index(&mut program);

    // Resolve imports
    let base_dir: Option<std::path::PathBuf> = if std::path::Path::new(source_arg).is_file() {
        std::path::Path::new(source_arg)
            .canonicalize()
            .ok()
            .and_then(|p| p.parent().map(|p| p.to_path_buf()))
    } else {
        None
    };
    let mut visited = std::collections::HashSet::new();
    let mut import_diagnostics: Vec<Diagnostic> = Vec::new();
    program.declarations = resolve_imports(
        program.declarations,
        base_dir.as_deref(),
        &mut visited,
        &mut import_diagnostics,
        BuildTarget::default(),
    );
    if !import_diagnostics.is_empty() {
        for d in &import_diagnostics {
            eprint!("{}", AnsiRenderer { use_color: true }.render(d));
        }
        return 1;
    }

    // Verify
    let verify_result = verify::verify(&program);
    for w in &verify_result.warnings {
        eprint!(
            "{}",
            AnsiRenderer { use_color: true }
                .render(&Diagnostic::from(w).with_source(source.clone()),)
        );
    }
    if !verify_result.errors.is_empty() {
        for e in &verify_result.errors {
            eprint!(
                "{}",
                AnsiRenderer { use_color: true }
                    .render(&Diagnostic::from(e).with_source(source.clone()),)
            );
        }
        return 1;
    }

    // `--py`: transpile to Python via the PythonBackend and short-circuit
    // before the bytecode/Cranelift pipeline runs.
    //
    // NOTE: like the Cranelift dispatch below, Python is a HIR-trait-surface
    // call with a side channel. The `_hir` argument is threaded for
    // signature parity, but the actual transpile reads `config.program`
    // (the verified AST) because the current HIR doesn't carry the full
    // expression-level surface Python emit needs (sum types, full match
    // shapes, etc.). See `backend/python/mod.rs` module doc and the
    // Backend trait doc for the wider story. The side channel is
    // documented and intentional in 0.13.0; it disappears once HIR grows.
    if python_mode {
        // Lower to HIR so the trait surface is HIR-first even if the Python
        // backend currently ignores it. Keeps the dispatch site uniform with
        // the Cranelift path.
        let hir = match ilo::hir::lower(&program, &verify_result) {
            Ok(h) => h,
            Err(e) => {
                eprintln!("HIR lowering error: {}", e);
                return 1;
            }
        };
        let config = ilo::backend::python::PythonConfig {
            program: &program,
            output_path: std::path::PathBuf::from(&output),
        };
        return match ilo::backend::python::emit(&hir, config) {
            Ok(_artefact) => {
                eprintln!("Compiled: {}", output);
                0
            }
            Err(e) => {
                eprintln!("Python transpile error: {}", e);
                1
            }
        };
    }

    // `--wasm`: emit a WebAssembly module via the WasmBackend. The default
    // target is wasm32-component (Component Model wrapper); `--target` lets
    // the user pick wasm32-wasip1, wasm32-wasip2, or wasm32-unknown-unknown.
    // See `backend/wasm/mod.rs` and `docs/wasm-capabilities.md` for the
    // per-target capability matrix.
    if wasm_mode {
        let target = match wasm_target_arg.as_deref() {
            None => ilo::backend::wasm::WasmTarget::Component,
            Some(s) => match ilo::backend::wasm::WasmTarget::parse(s) {
                Some(t) => t,
                None => {
                    eprintln!(
                        "Error: unknown --target `{}`. Supported: wasm32-wasip1, wasm32-wasip2, wasm32-component, wasm32-unknown-unknown (alias wasm32-web)",
                        s
                    );
                    return 1;
                }
            },
        };
        let hir = match ilo::hir::lower(&program, &verify_result) {
            Ok(h) => h,
            Err(e) => {
                eprintln!("HIR lowering error: {}", e);
                return 1;
            }
        };
        let config = ilo::backend::wasm::WasmConfig {
            target,
            output_path: std::path::PathBuf::from(&output),
            entry: func_name.map(|s| s.to_string()),
        };
        return match ilo::backend::wasm::emit(&hir, config) {
            Ok(_artefact) => {
                eprintln!("Compiled: {}", output);
                0
            }
            Err(e) => {
                eprintln!("WASM compile error: {}", e);
                1
            }
        };
    }

    // `--0` / `--0bin`: emit Zero source (`.0`) via the ZeroBackend.
    // `--0bin` chains through the pinned `zero` compiler (0.1.2) to produce
    // a native binary. See `backend/zero/mod.rs` and
    // `docs/zero-transpile-capabilities.md` for the capability matrix.
    if zero_mode || zero_bin_mode {
        let hir = match ilo::hir::lower(&program, &verify_result) {
            Ok(h) => h,
            Err(e) => {
                eprintln!("HIR lowering error: {}", e);
                return 1;
            }
        };
        let mode = if zero_bin_mode {
            ilo::backend::zero::ZeroMode::Binary
        } else {
            ilo::backend::zero::ZeroMode::Source
        };
        let config = ilo::backend::zero::ZeroConfig {
            output_path: std::path::PathBuf::from(&output),
            mode,
            entry: func_name.map(|s| s.to_string()),
        };
        return match ilo::backend::zero::emit(&hir, config) {
            Ok(_artefact) => {
                eprintln!("Compiled: {}", output);
                0
            }
            Err(e) => {
                eprintln!("Zero transpile error: {}", e);
                1
            }
        };
    }

    // Compile to bytecode
    let compiled = match vm::compile(&program) {
        Ok(c) => c,
        Err(e) => {
            eprintln!("Compile error: {}", e);
            return 1;
        }
    };

    // Determine entry function.
    //
    // AOT historically picked `func_names.first()` here, which meant a file
    // like `helper>n;42\nmain>n;helper` compiled with the helper as the
    // entry symbol — the produced binary then SIGSEGV'd at runtime because
    // the wrapper expected `main`'s shape. Tree/VM/JIT all canonicalise on
    // `main` (or the single-fn shortcut) via the dispatch in `run_cmd`; AOT
    // now mirrors that convention exactly:
    //
    //   1. explicit positional `func` argument wins
    //   2. else single user-defined function (the `m>...` test idiom) → use it
    //   3. else `main` exists → use `main`
    //   4. else error ILO-E801 with the available-function list, exit 1
    //      (never SIGSEGV)
    let user_fn_names: Vec<&str> = program
        .declarations
        .iter()
        .filter_map(|d| match d {
            ast::Decl::Function { name, .. } | ast::Decl::Tool { name, .. }
                if !name.starts_with("__") =>
            {
                Some(name.as_str())
            }
            _ => None,
        })
        .collect();

    let entry: &str = if let Some(name) = func_name {
        name
    } else if user_fn_names.len() == 1 {
        user_fn_names[0]
    } else if user_fn_names.contains(&"main") {
        "main"
    } else {
        eprintln!(
            "error[ILO-E801]: AOT compile needs an entry function but no `main` is defined and no entry name was supplied"
        );
        if user_fn_names.is_empty() {
            eprintln!("note: this file declares no functions");
        } else {
            eprintln!("available functions:");
            for n in &user_fn_names {
                eprintln!("  {}", n);
            }
        }
        eprintln!();
        eprintln!(
            "  ilo compile {} <func>          compile and call <func> as the entry point",
            source_arg
        );
        eprintln!(
            "  ilo compile {} -o <out> <func> compile to <out> with <func> as the entry point",
            source_arg
        );
        return 1;
    };

    // Lower verified AST to HIR. The Cranelift backend ignores it today
    // (Stage 5b uses bytecode via the config side-channel) but the dispatch
    // surface is HIR-first so subsequent stages can swap backends without
    // touching `main.rs`.
    let hir = match ilo::hir::lower(&program, &verify_result) {
        Ok(h) => h,
        Err(e) => {
            eprintln!("HIR lowering error: {}", e);
            return 1;
        }
    };

    // AOT compile via the backend trait surface.
    let start = std::time::Instant::now();
    let config = ilo::backend::cranelift::CraneliftConfig {
        program: &compiled,
        entry,
        output_path: &output,
        bench: bench_mode,
    };
    let result = ilo::backend::cranelift::emit(&hir, config);
    let duration_ms = start.elapsed().as_millis();
    match result {
        Ok(_artefact) => {
            if as_json {
                let size_bytes = std::fs::metadata(&output).map(|m| m.len()).ok();
                let v = serde_json::json!({
                    "schemaVersion": 1,
                    "ok": true,
                    "output": output,
                    "entry": entry,
                    "bench": bench_mode,
                    "sizeBytes": size_bytes,
                    "durationMs": duration_ms,
                });
                println!("{}", v);
            } else {
                eprintln!("Compiled: {}", output);
            }
            0
        }
        Err(e) => {
            if as_json {
                let v = serde_json::json!({
                    "schemaVersion": 1,
                    "ok": false,
                    "error": {
                        "phase": "aot-compile",
                        "message": e.to_string(),
                    }
                });
                println!("{}", v);
            } else {
                eprintln!("AOT compile error: {}", e);
            }
            1
        }
    }
}

#[cfg(not(feature = "cranelift"))]
fn compile_cmd(args: &[String]) -> i32 {
    if args.iter().any(|a| a == "--help" || a == "-h") {
        print_build_help();
        return 0;
    }
    eprintln!("Error: AOT compilation requires the cranelift feature (--features cranelift)");
    1
}

/// Manifesto-strict `ilo build` help. Exactly five forms.
///
/// Emitted on stderr so it composes with the friendly-usage handlers in
/// `main()` (which also use stderr) and matches the wider unix-y convention
/// of usage/help being a diagnostic rather than program output.
fn print_build_help() {
    eprintln!("ilo build — compile an ilo program\n");
    eprintln!("Usage:");
    eprintln!("  ilo build <file.ilo>              Native binary (default; Cranelift)");
    eprintln!("  ilo build <file.ilo> --wasm       WebAssembly Component Model binary");
    eprintln!("  ilo build <file.ilo> --0          Zero source (.0)");
    eprintln!("  ilo build <file.ilo> --0bin       Native binary via the Zero compiler");
    eprintln!("  ilo build <file.ilo> --py         Python source (.py)\n");
    eprintln!("Options:");
    eprintln!("  -o <path>          Output path (default: alongside the source)");
    eprintln!("  --target <name>    For --wasm: wasm32-component (default),");
    eprintln!("                     wasm32-wasip1, wasm32-wasip2, wasm32-unknown-unknown");
    eprintln!("  --help / -h        Show this help");
}

/// Stdio-based agent serve loop.
/// Reads one JSON request per line from stdin, writes one JSON response per line to stdout.
fn serv_cmd(args_slice: &[String]) {
    let mut mcp_path: Option<String> = None;
    let mut http_path: Option<String> = None;

    let mut i = 0;
    while i < args_slice.len() {
        match args_slice[i].as_str() {
            "--mcp" | "-m" => {
                if i + 1 >= args_slice.len() {
                    eprintln!("error: --mcp requires a path");
                    std::process::exit(1);
                }
                mcp_path = Some(args_slice[i + 1].clone());
                i += 2;
            }
            "--tools" | "-t" => {
                if i + 1 >= args_slice.len() {
                    eprintln!("error: --tools requires a path");
                    std::process::exit(1);
                }
                http_path = Some(args_slice[i + 1].clone());
                i += 2;
            }
            "-j" | "--json" => {
                // JSON protocol is always on in repl/serv; flag is a no-op (accepted for alias compat)
                i += 1;
            }
            _ => {
                eprintln!("unknown flag: {}", args_slice[i]);
                eprintln!("Usage: ilo repl [-j] [--mcp <path>] [--tools <path>]");
                std::process::exit(1);
            }
        }
    }

    // Load HTTP config (sync)
    let http_config: Option<tools::http_provider::ToolsConfig> = http_path.as_ref().map(|p| {
        tools::http_provider::ToolsConfig::from_file(p).unwrap_or_else(|e| {
            eprintln!("{}", e);
            std::process::exit(1);
        })
    });

    // Create tokio runtime once (used for MCP connect + all tool calls)
    #[cfg(feature = "tools")]
    let rt = std::sync::Arc::new(
        tokio::runtime::Builder::new_current_thread()
            .enable_all()
            .build()
            .expect("tokio runtime"),
    );

    // Connect to MCP once, keep provider + static decls alive for all requests
    #[cfg(feature = "tools")]
    let (mcp_tool_decls, mcp_provider_arc): (
        Vec<ast::Decl>,
        Option<std::sync::Arc<dyn tools::ToolProvider>>,
    ) = if let Some(ref path) = mcp_path {
        let config = tools::mcp_provider::McpConfig::from_file(path).unwrap_or_else(|e| {
            eprintln!("{}", e);
            std::process::exit(1);
        });
        let provider = rt
            .block_on(tools::mcp_provider::McpProvider::connect(&config))
            .unwrap_or_else(|e| {
                eprintln!("MCP error: {}", e);
                std::process::exit(1);
            });
        let decls = provider.tool_decls();
        (decls, Some(std::sync::Arc::new(provider)))
    } else {
        (vec![], None)
    };

    #[cfg(not(feature = "tools"))]
    let mcp_tool_decls: Vec<ast::Decl> = {
        if mcp_path.is_some() {
            eprintln!(
                "error: --mcp requires the 'tools' feature \
                 (build with: cargo build --features tools)"
            );
            std::process::exit(1);
        }
        vec![]
    };

    // Signal ready
    println!("{}", serde_json::json!({"schemaVersion": 1, "ready": true}));

    use std::io::BufRead;
    let stdin = std::io::stdin();
    for line in stdin.lock().lines() {
        let line = match line {
            Ok(l) => l,
            Err(e) => {
                eprintln!("stdin read error: {}", e);
                break;
            }
        };
        if line.trim().is_empty() {
            continue;
        }

        let resp = process_serv_request(
            &line,
            &mcp_tool_decls,
            #[cfg(feature = "tools")]
            mcp_provider_arc.as_ref().map(std::sync::Arc::clone),
            http_config.as_ref(),
            #[cfg(feature = "tools")]
            std::sync::Arc::clone(&rt),
        );
        println!("{}", resp);
    }
}

/// Scan args for `--vm` / `--run-vm` / `--jit` / `--run-llvm` anywhere in the
/// list and remove them. argv[0] (binary name) is preserved at position 0.
/// Returns the chosen engine (if any) plus the remaining args. Multiple
/// conflicting engine flags produce an error. `--jit` opts into the Cranelift
/// JIT for hot numeric loops; the implementation name (Cranelift) is kept
/// internal so the user-facing flag names the concept, not the backend.
///
/// `--run-vm` is a one-release transitional alias for `--vm`. When the alias
/// is seen, a one-shot deprecation hint is emitted on stderr. Removal planned
/// for 0.13.0.
///
/// `--run-tree` / `--run` are NOT recognised here as part of the tree-walker
/// soft-deprecation. They fall through to the unknown-flag guard, which
/// surfaces a clear error suggesting `--vm` or `--jit`. The tree-walker
/// stays in-tree as the HOF-callback runtime; it's just no longer
/// user-selectable on the CLI.
fn extract_run_engine_flag(
    args: Vec<String>,
) -> Result<(Option<cli::Engine>, Vec<String>), String> {
    let mut engine: Option<cli::Engine> = None;
    let mut conflict = false;
    let mut saw_run_vm_alias = false;
    let mut remaining = Vec::with_capacity(args.len());

    for arg in args {
        let candidate = match arg.as_str() {
            "--jit" => Some(cli::Engine::Cranelift),
            "--run-llvm" => Some(cli::Engine::Llvm),
            "--vm" => Some(cli::Engine::Vm),
            "--run-vm" => {
                saw_run_vm_alias = true;
                Some(cli::Engine::Vm)
            }
            _ => None,
        };
        match candidate {
            Some(e) => match engine {
                None => engine = Some(e),
                Some(prev) if prev == e => {} // identical flag repeated: ignore
                Some(_) => conflict = true,
            },
            None => remaining.push(arg),
        }
    }

    if conflict {
        return Err("error: --vm, --jit, --run-llvm are mutually exclusive".to_string());
    }

    if saw_run_vm_alias {
        emit_run_vm_alias_hint();
    }

    Ok((engine, remaining))
}

/// One-shot stderr hint when the user passes `--run-vm`. The alias is kept
/// for one release so existing carry-forward scripts/personas don't break,
/// but every invocation gets a single line nudging them to the canonical
/// `--vm` spelling. Removal lands in 0.13.0 alongside the tree-walker
/// hard-removal pass.
fn emit_run_vm_alias_hint() {
    use std::sync::atomic::{AtomicBool, Ordering};
    static EMITTED: AtomicBool = AtomicBool::new(false);
    if EMITTED.swap(true, Ordering::Relaxed) {
        return;
    }
    eprintln!(
        "hint: --run-vm → --vm (canonical form). The --run-vm alias will be removed in 0.13.0."
    );
}

/// Scan args for --json/-j, --text/-t, --ansi/-a, --no-hints/-nh, --silent/-s.
/// Return (mode, explicit_json, no_hints, silent, remaining_args).
/// Multiple format flags -> error + exit(1).
/// `explicit_json` is true only when the user passed --json/-j; auto-detection never sets it.
fn detect_output_mode(args: Vec<String>) -> (OutputMode, bool, bool, bool, Vec<String>) {
    let mut mode: Option<OutputMode> = None;
    let mut remaining = Vec::with_capacity(args.len());
    let mut conflict = false;
    let mut no_hints = false;
    let mut silent = false;

    for arg in args {
        match arg.as_str() {
            "--json" | "-j" => {
                if mode.is_some() {
                    conflict = true;
                } else {
                    mode = Some(OutputMode::Json);
                }
            }
            "--text" | "-t" => {
                if mode.is_some() {
                    conflict = true;
                } else {
                    mode = Some(OutputMode::Text);
                }
            }
            "--ansi" | "-a" => {
                if mode.is_some() {
                    conflict = true;
                } else {
                    mode = Some(OutputMode::Ansi);
                }
            }
            "--no-hints" | "-nh" => {
                no_hints = true;
            }
            "--silent" | "-s" => {
                silent = true;
            }
            _ => remaining.push(arg),
        }
    }

    if conflict {
        eprintln!("error: --json, --text, and --ansi are mutually exclusive");
        std::process::exit(1);
    }

    let explicit_json = matches!(mode, Some(OutputMode::Json));

    let resolved = mode.unwrap_or_else(|| {
        // Auto-detect: isatty(stderr) && !NO_COLOR → Ansi; isatty && NO_COLOR → Text; !isatty → Json
        use std::io::IsTerminal;
        let is_tty = std::io::stderr().is_terminal();
        let no_color = std::env::var("NO_COLOR").is_ok();
        if is_tty && !no_color {
            OutputMode::Ansi
        } else if is_tty {
            OutputMode::Text
        } else {
            OutputMode::Json
        }
    });

    (resolved, explicit_json, no_hints, silent, remaining)
}

/// Replace the contents of string literals with spaces, preserving length.
/// `"https://x.com"` → `"               "`. This prevents cross-language pattern
/// detection from matching inside strings (e.g. `//` in URLs).
fn strip_string_contents(source: &str) -> String {
    let mut result = String::with_capacity(source.len());
    let mut in_string = false;
    let mut chars = source.chars().peekable();
    while let Some(c) = chars.next() {
        if in_string {
            if c == '\\' {
                // Escaped character — skip both backslash and next char
                result.push(' ');
                if chars.next().is_some() {
                    result.push(' ');
                }
            } else if c == '"' {
                result.push('"');
                in_string = false;
            } else {
                result.push(' ');
            }
        } else if c == '"' {
            result.push('"');
            in_string = true;
        } else {
            result.push(c);
        }
    }
    result
}

/// Collect idiomatic hints by scanning source text for non-canonical forms.
/// Returns a list of human-readable hint strings.
///
/// Word-boundary scans (alias hints) run over real lexer tokens, not raw text:
/// re-lexing skips comments, strings, numbers, operators, and CLI argv, so a
/// `tail` substring inside a comment line, a string literal, or a file path
/// printed to stderr won't fire `hint: \`tail\` → \`tl\``. The text-based `==`
/// scan strips both strings and comments first for the same reason.
#[cfg(test)]
fn collect_hints(source: &str) -> Vec<String> {
    collect_hints_with_program(source, None)
}

fn collect_hints_with_program(source: &str, program: Option<&ast::Program>) -> Vec<String> {
    let mut hints = Vec::new();
    // Hint: == → = saves 1 character
    // Scan for `==` outside string literals and comments. We don't use the
    // lexer here because logos collapses both `=` and `==` into `Token::Eq`,
    // so the distinction is only visible in raw text.
    let stripped = strip_string_and_comment_contents(source);
    let mut pos = 0;
    let bytes = stripped.as_bytes();
    while pos + 1 < bytes.len() {
        if bytes[pos] == b'=' && bytes[pos + 1] == b'=' {
            hints.push("hint: `==` → `=` saves 1 char (both mean equality in ilo)".to_string());
            break; // one hint per pattern type is enough
        }
        pos += 1;
    }
    // Hint: long-form builtin aliases → canonical short form.
    // Use lexer tokens so we only consider real source identifiers — not words
    // appearing in comments, string literals, or anything outside the source
    // itself. Falling back to no hint on lex failure is fine: the run already
    // succeeded if we got here, so a re-lex failure is implausible, but we
    // err on the side of "no hint" rather than spurious noise.
    if let Ok(tokens) = lexer::lex(source) {
        for (tok, _) in &tokens {
            if let lexer::Token::Ident(word) = tok
                && let Some(canonical) = ast::resolve_alias(word)
            {
                hints.push(format!("hint: `{word}` → `{canonical}` (canonical form)"));
                break; // one hint per run is enough
            }
        }
        // Hint: same-precedence prefix-arithmetic-op pairs trip the
        // left-to-right intuition. `*/a b c` parses as `*(/a b) c == (a/b)*c`
        // because the first prefix op binds the nested prefix subexpression as
        // its LEFT operand. Personas reading `* / a b c` left-to-right expect
        // `(a*b)/c` and silently get the wrong answer. Fire on the four mixed
        // same-precedence pairs (`*/`, `/*`, `+-`, `-+`) when both tokens are
        // in prefix position (previous token is not a value-yielding atom).
        // Same-op repeats like `++a b c == (a+b)+c` already match left-to-right
        // intuition and are skipped.
        if let Some(hint) = detect_prefix_precedence_trap(&tokens) {
            hints.push(hint);
        }
    }
    // AST-aware hint: braced-conditional guard `cond{^"err"}` discards the
    // body value as the function's return path — almost always not what the
    // author intended. Personas (qa-tester, scientific-researcher rerun3,
    // config-shaper + bioinformatics rerun10) reach for this shape expecting
    // early-return semantics. The braceless form `<k 1 ^"err"` or explicit
    // `ret` inside the braces covers the real intent.
    if let Some(prog) = program {
        for decl in &prog.declarations {
            if let ast::Decl::Function { body, .. } = decl
                && walk_for_discarded_guard_result(body)
            {
                hints.push(
                    "hint: `cond{^\"err\"}` and `cond{~v}` discard the body expression. For early-return use the braceless form `cond ^\"err\"` or wrap the body in `{ret ^\"err\"}`."
                        .to_string(),
                );
                break; // one hint per run is enough
            }
        }
    }
    hints
}

/// Walk a body looking for a braced-conditional guard whose final body
/// statement is an `Expr::Err(_)` or `Expr::Ok(_)` expression — a strong
/// signal the author meant `ret ^...` / `ret ~...` but wrote `cond{^...}`,
/// which silently discards the value from the function's return path under
/// the braced-guard semantics.
fn walk_for_discarded_guard_result(body: &[ast::Spanned<ast::Stmt>]) -> bool {
    for s in body {
        if walk_stmt_for_discarded_guard_result(&s.node) {
            return true;
        }
    }
    false
}

fn walk_stmt_for_discarded_guard_result(stmt: &ast::Stmt) -> bool {
    match stmt {
        ast::Stmt::Guard {
            body,
            else_body,
            braceless,
            ..
        } => {
            // Only fire on the original target shape: a single-statement
            // braced body whose sole expression is `^...` or `~...`. The
            // single-statement requirement matters because multi-statement
            // bodies like `{prnt "..."; ~"ok"}` legitimately use the trailing
            // `~v` as the body's return value — the author knows the value
            // is the guard's result, not a discarded early-return. Firing
            // there is a false positive that erodes trust in the hint.
            if !*braceless
                && body.len() == 1
                && let Some(only) = body.first()
                && matches!(
                    only.node,
                    ast::Stmt::Expr(ast::Expr::Err(_) | ast::Expr::Ok(_))
                )
            {
                return true;
            }
            if walk_for_discarded_guard_result(body) {
                return true;
            }
            if let Some(eb) = else_body
                && walk_for_discarded_guard_result(eb)
            {
                return true;
            }
            false
        }
        ast::Stmt::Match { arms, .. } => arms
            .iter()
            .any(|a| walk_for_discarded_guard_result(&a.body)),
        ast::Stmt::ForEach { body, .. }
        | ast::Stmt::ForRange { body, .. }
        | ast::Stmt::While { body, .. } => walk_for_discarded_guard_result(body),
        _ => false,
    }
}

/// Detect same-precedence prefix-arithmetic-op pairs that parse in a way
/// that contradicts the human left-to-right reading. Returns `Some(hint)` for
/// the first such occurrence, or `None`.
///
/// Pattern: `<op1> <op2>` adjacent at a prefix position, where:
///   * `(op1, op2)` is one of `(*, /)`, `(/, *)`, `(+, -)`, `(-, +)`
///   * The token before `op1` is start-of-input or a non-value-yielding
///     token (so `op1` is genuinely in prefix position, not infix).
///   * `op2` is followed by at least one value-yielding token (otherwise
///     it isn't a prefix op either).
///
/// We rely on the lexer's greedy-negative-literal rule (`-5` lexes as
/// `Number(-5)`, not `Minus, Number(5)`), so `*-5 b c` will NOT match this
/// pattern — the negative literal absorbs the minus. Spelt-out `*- 5 b c`
/// (with a space) does lex as `Star, Minus, Number, Ident`, and is a true
/// prefix-pair: fire.
///
/// Suppression: when the immediate predecessor of `op1` is `LParen`, the
/// author has explicitly grouped the prefix expression. The parenthesised
/// form is the recommended shape (the hint itself suggests grouping as the
/// canonical disambiguation), so flagging it would be self-contradictory.
/// Nested parens are covered too because the immediate predecessor of `op1`
/// is still `LParen` in `((/ *a b c))`.
fn detect_prefix_precedence_trap(
    tokens: &[(lexer::Token, std::ops::Range<usize>)],
) -> Option<String> {
    use lexer::Token::*;
    for i in 0..tokens.len().saturating_sub(1) {
        let op1 = &tokens[i].0;
        let op2 = &tokens[i + 1].0;
        // (shape, parsed_as, swap_form, bind_form). `bind_form` shows the
        // explicit two-statement rewrite that yields the OTHER grouping, so
        // the persona has both a concrete swap example and a concrete bind
        // example to copy.
        let pair = match (op1, op2) {
            (Star, Slash) => Some(("*/", "(a/b)*c", "/*a b c", "r=*a b;/r c")),
            (Slash, Star) => Some(("/*", "(a*b)/c", "*/a b c", "r=/a b;*r c")),
            (Plus, Minus) => Some(("+-", "(a-b)+c", "-+a b c", "r=+a b;- r c")),
            (Minus, Plus) => Some(("-+", "(a+b)-c", "+-a b c", "r=-a b;+r c")),
            _ => None,
        };
        let Some((shape, parsed_as, swap_form, bind_form)) = pair else {
            continue;
        };
        // Prefix-position check: the previous token must not be value-yielding.
        if i > 0 && is_value_yielding(&tokens[i - 1].0) {
            continue;
        }
        // Explicit-grouping suppression: if op1 sits directly after an
        // opening delimiter (`(`, `[`, `{`), the author has bounded the
        // prefix subexpression with explicit grouping. The hint suggests
        // grouping as the canonical disambiguation, so firing here would be
        // self-contradictory. Includes `[` for list literals (`[*/a b c]`)
        // and `{` for block bodies / braced conditionals (`cond{*/a b c}`),
        // both of which several rerun7 personas (content-mod, ab-tester,
        // logs-forensics, scientific-researcher) hit as a false positive.
        // Nested delimiters are covered too because the immediate
        // predecessor remains the innermost opener.
        if i > 0 && matches!(&tokens[i - 1].0, LParen | LBracket | LBrace) {
            continue;
        }
        // The pair must be followed by at least one value-yielding token to
        // function as prefix ops. Otherwise it isn't a prefix pair at all.
        if i + 2 >= tokens.len() || !is_value_yielding(&tokens[i + 2].0) {
            continue;
        }
        return Some(format!(
            "hint: `{shape}a b c` parses as `{parsed_as}` (inner prefix op binds first). \
             For the other order, swap the ops (`{swap_form}`) or bind: `{bind_form}`",
        ));
    }
    None
}

/// Tokens that yield a value, used to distinguish prefix position from infix.
/// If the token immediately before an operator yields a value, the operator
/// is being used in infix form (e.g. `x * y`), not prefix.
fn is_value_yielding(tok: &lexer::Token) -> bool {
    use lexer::Token::*;
    matches!(
        tok,
        Ident(_)
            | Number(_)
            | Text(_)
            | True
            | False
            | Nil
            | RParen
            | RBracket
            | RBrace
            | Bang
            | BangBang
    )
}

/// Strip both string-literal contents and `--`-prefixed line comments,
/// replacing their contents with spaces so byte offsets are preserved.
/// Used by the text-based `==` scan so a literal `==` inside a string or
/// comment doesn't trigger the hint.
fn strip_string_and_comment_contents(source: &str) -> String {
    let stripped = strip_string_contents(source);
    let mut out = String::with_capacity(stripped.len());
    let mut chars = stripped.chars().peekable();
    let mut in_comment = false;
    while let Some(c) = chars.next() {
        if in_comment {
            if c == '\n' {
                in_comment = false;
                out.push(c);
            } else {
                out.push(' ');
            }
        } else if c == '-' && chars.peek() == Some(&'-') {
            // Consume the second '-' and enter comment mode
            chars.next();
            out.push(' ');
            out.push(' ');
            in_comment = true;
        } else {
            out.push(c);
        }
    }
    out
}

/// Emit hints to the appropriate output channel.
/// TTY → stderr, JSON → adds to JSON output (caller handles), pipe → nothing.
fn emit_hints(hints: &[String], mode: OutputMode) {
    if hints.is_empty() {
        return;
    }
    match mode {
        OutputMode::Ansi | OutputMode::Text => {
            for hint in hints {
                eprintln!("{hint}");
            }
        }
        OutputMode::Json => {
            // JSON mode: hints go to stderr as JSON array
            let json = serde_json::json!({ "hints": hints });
            eprintln!("{}", json);
        }
    }
}

/// Scan source for common cross-language patterns and emit a single warning if found.
/// Non-fatal — program still attempts to run.
fn warn_cross_language_syntax(source: &str, mode: OutputMode) {
    let patterns: &[(&str, &str)] = &[
        ("&&", "'&&' — ilo uses '&' for AND"),
        ("||", "'||' — ilo uses '|' for OR"),
        ("->", "'->' — ilo uses '>' for return type separator"),
        ("//", "'//' — ilo uses '--' for comments"),
    ];

    // Strip string literal contents AND `--` comments so patterns inside
    // `"..."` or `--` lines don't trigger warnings. Avoids false positives
    // for URLs like `"https://example.com"` and for comments that mention
    // cross-language syntax illustratively (e.g. `-- not: a -> b`).
    let stripped = strip_string_and_comment_contents(source);

    let details: Vec<&str> = patterns
        .iter()
        .filter(|(pat, _)| stripped.contains(*pat))
        .map(|(_, desc)| *desc)
        .collect();

    if details.is_empty() {
        return;
    }

    let msg = format!(
        "source contains syntax from another language: {}",
        details.join(", ")
    );
    let d = Diagnostic::warning(msg);
    report_diagnostic(&d, mode);
}

/// Return the declared name of a `Decl`, if it has one.
fn decl_name(decl: &ast::Decl) -> Option<&str> {
    match decl {
        ast::Decl::Function { name, .. } => Some(name),
        ast::Decl::Tool { name, .. } => Some(name),
        ast::Decl::TypeDef { name, .. } => Some(name),
        ast::Decl::Alias { name, .. } => Some(name),
        ast::Decl::SumType { name, .. } => Some(name),
        ast::Decl::Use { .. } | ast::Decl::Error { .. } => None,
    }
}

/// Build target used to evaluate conditional `use ?<pred>` predicates.
///
/// Passed to `resolve_imports` so that `use ?wasm "a" : "b"` picks the
/// right branch at compile time without touching the runtime.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum BuildTarget {
    /// Native host binary (default).
    #[default]
    Native,
    /// WebAssembly (wasm32) target.
    Wasm,
    /// Test run (`ilo test`).
    Test,
}

impl BuildTarget {
    /// Evaluate a `UsePredicate` against this target: returns `true` when
    /// the predicate matches (i.e. the "true" branch should be imported).
    pub fn eval(self, pred: ast::UsePredicate) -> bool {
        matches!(
            (self, pred),
            (BuildTarget::Wasm, ast::UsePredicate::Wasm)
                | (BuildTarget::Native, ast::UsePredicate::Native)
                | (BuildTarget::Test, ast::UsePredicate::Test)
        )
    }
}

/// Apply the `only [name1 name2]` filter from a `use` statement.
/// Pushes `ILO-P019` diagnostics for names not found.
fn apply_only_filter(
    decls: Vec<ast::Decl>,
    only: &Option<Vec<String>>,
    path: &str,
    span: ast::Span,
    diagnostics: &mut Vec<Diagnostic>,
) -> Vec<ast::Decl> {
    let Some(names) = only else {
        return decls;
    };
    for name in names {
        let found = decls.iter().any(|d| decl_name(d) == Some(name.as_str()));
        if !found {
            diagnostics.push(
                Diagnostic::error(format!(
                    "use \"{}\": name '{}' not found in imported file",
                    path, name
                ))
                .with_code("ILO-P019")
                .with_span(span, "imported here"),
            );
        }
    }
    decls
        .into_iter()
        .filter(|d| {
            decl_name(d)
                .map(|n| names.iter().any(|s| s == n))
                .unwrap_or(false)
        })
        .collect()
}

/// Resolve all `Decl::Use` nodes in `decls` recursively, returning a flat
/// merged list with imported declarations prepended and `Use` nodes stripped.
///
/// - `base_dir`: directory of the importing file (used to resolve relative paths).
///   `None` means inline code — `use` is not supported without a file context.
/// - `visited`: canonical paths already in the import chain; circular imports are errors.
/// - `diagnostics`: errors are pushed here (file-not-found, circular, parse failures).
/// - `build_target`: evaluates `use ?<pred>` predicates at compile time.
///
/// Privacy rule: declarations whose name starts with `_` are module-private and
/// are never exported. They are stripped during import regardless of `only` or `alias`.
///
/// Lazy imports (`use lazy:"./path"`) are deferred: the module file is only
/// opened if at least one `<stem>-*` symbol is referenced in the non-lazy
/// declarations. This lets large optional modules be listed without paying
/// any parse/IO cost when unused.
fn resolve_imports(
    decls: Vec<ast::Decl>,
    base_dir: Option<&std::path::Path>,
    visited: &mut std::collections::HashSet<std::path::PathBuf>,
    diagnostics: &mut Vec<Diagnostic>,
    build_target: BuildTarget,
) -> Vec<ast::Decl> {
    // Separate lazy Use nodes from everything else for a two-pass approach.
    let mut eager_decls: Vec<ast::Decl> = Vec::new();
    let mut lazy_pending: Vec<ast::Decl> = Vec::new();
    for decl in decls {
        if matches!(&decl, ast::Decl::Use { lazy: true, .. }) {
            lazy_pending.push(decl);
        } else {
            eager_decls.push(decl);
        }
    }

    // Pass 1: resolve all eager (non-lazy) declarations.
    let mut result = resolve_imports_inner(
        eager_decls,
        base_dir,
        visited,
        diagnostics,
        build_target,
        false,
    )
    .0;

    // Pass 2: for each lazy pending import, check if any `<alias>-*` symbol
    // is referenced in the already-resolved declarations. Only load if so.
    for decl in lazy_pending {
        if let ast::Decl::Use { ref alias, .. } = decl {
            let prefix = format!("{}-", alias.as_deref().unwrap_or(""));
            if decls_reference_prefix(&result, &prefix) {
                // Symbol is used — load the module via the eager path.
                let loaded = resolve_imports_inner(
                    vec![decl],
                    base_dir,
                    visited,
                    diagnostics,
                    build_target,
                    false,
                )
                .0;
                // Prepend so lazy module decls precede the importer's own decls.
                let mut combined = loaded;
                combined.extend(result);
                result = combined;
            }
            // else: no reference to this module — skip loading entirely.
        }
    }

    result
}

/// Resolves imports and returns `(all_decls, exported_names)`.
///
/// `all_decls` contains every declaration that is in scope for the current module
/// (own declarations + all transitively-imported declarations). This is what the
/// module uses internally.
///
/// `exported_names` is the *public surface* of this module — the names that
/// consumers of this module can import. It includes:
///   - Every own declaration whose name does not start with `_`
///   - Any declaration brought in via `use re:"path" [names]` (re-exports)
///
/// When `for_export` is `false` (entry-point / top-level call), the second return
/// value is not meaningful and the caller should ignore it.
fn resolve_imports_inner(
    decls: Vec<ast::Decl>,
    base_dir: Option<&std::path::Path>,
    visited: &mut std::collections::HashSet<std::path::PathBuf>,
    diagnostics: &mut Vec<Diagnostic>,
    build_target: BuildTarget,
    for_export: bool,
) -> (Vec<ast::Decl>, Vec<String>) {
    let _ = for_export; // used by callers; kept for future use
    let mut result: Vec<ast::Decl> = Vec::new();
    // Track which names in `result` are part of the public export surface.
    let mut exported_names: std::collections::HashSet<String> = std::collections::HashSet::new();

    for decl in decls {
        if let ast::Decl::Use {
            path,
            only,
            alias,
            predicate,
            alt_path,
            reexport,
            lazy: _,
            span,
        } = decl
        {
            // For conditional imports, select the right branch now.
            let path = if let Some(pred) = predicate {
                if build_target.eval(pred) {
                    path
                } else {
                    // alt_path is guaranteed to be Some when predicate is Some
                    // (enforced by the parser).
                    alt_path.unwrap_or(path)
                }
            } else {
                path
            };

            // ── Package registry resolution ───────────────────────────────────
            // `use "owner/repo"` (first component has no `.`) resolves through
            // the local package cache at ~/.ilo/pkgs/<owner>/<repo>/index.ilo.
            if ilo::pkg::is_pkg_path(&path) {
                let resolved = ilo::pkg::resolve_pkg_path(&path);
                match resolved {
                    Err(msg) => {
                        diagnostics.push(
                            Diagnostic::error(format!("use \"{path}\": {msg}"))
                                .with_code("ILO-P017")
                                .with_span(span, "imported here"),
                        );
                        continue;
                    }
                    Ok(pkg_file) => {
                        // Synthesise a Use decl for the resolved file path and
                        // re-use the same local-file resolution path below by
                        // substituting the resolved path into a local Use node.
                        let abs = pkg_file.to_string_lossy().into_owned();
                        let synthetic = ast::Decl::Use {
                            path: abs,
                            only: only.clone(),
                            alias: alias.clone(),
                            predicate: None,
                            alt_path: None,
                            reexport: false,
                            lazy: false,
                            span,
                        };
                        let mut sub = resolve_imports(
                            vec![synthetic],
                            None, // abs path, base_dir not needed
                            visited,
                            diagnostics,
                            build_target,
                        );
                        result.append(&mut sub);
                        continue;
                    }
                }
            }

            // ── Local file resolution ─────────────────────────────────────────
            let Some(dir) = base_dir else {
                // Package paths are handled above; inline code cannot use local files.
                // Absolute paths (synthesised by package resolution) are also handled above.
                if path.starts_with('/') {
                    // Absolute path synthesised by package resolution — resolve directly.
                    let canonical = match std::path::PathBuf::from(&path).canonicalize() {
                        Ok(c) => c,
                        Err(_) => {
                            diagnostics.push(
                                Diagnostic::error(format!("use \"{}\": file not found", path))
                                    .with_code("ILO-P017")
                                    .with_span(span, "imported here"),
                            );
                            continue;
                        }
                    };
                    // Proceed with the canonical path as if base_dir were its parent.
                    let imported_dir = canonical.parent().map(|p| p.to_path_buf());
                    let source = match std::fs::read_to_string(&canonical) {
                        Ok(s) => s,
                        Err(e) => {
                            diagnostics.push(
                                Diagnostic::error(format!("use \"{}\": {}", path, e))
                                    .with_code("ILO-P017")
                                    .with_span(span, "imported here"),
                            );
                            continue;
                        }
                    };
                    if visited.contains(&canonical) {
                        diagnostics.push(
                            Diagnostic::error(format!("use \"{}\": circular import", path))
                                .with_code("ILO-P018")
                                .with_span(span, "imported here"),
                        );
                        continue;
                    }
                    let tokens = match lexer::lex(&source) {
                        Ok(t) => t,
                        Err(e) => {
                            diagnostics.push(Diagnostic::from(&e));
                            continue;
                        }
                    };
                    let token_spans: Vec<(lexer::Token, ast::Span)> = tokens
                        .into_iter()
                        .map(|(t, r)| {
                            (
                                t,
                                ast::Span {
                                    start: r.start,
                                    end: r.end,
                                },
                            )
                        })
                        .collect();
                    let (mut imported_prog, parse_errors) = parser::parse(token_spans);
                    ast::resolve_aliases(&mut imported_prog);
                    ast::desugar_dot_var_index(&mut imported_prog);
                    for e in &parse_errors {
                        diagnostics.push(Diagnostic::from(e));
                    }
                    visited.insert(canonical.clone());
                    let imported_decls = resolve_imports(
                        imported_prog.declarations,
                        imported_dir.as_deref(),
                        visited,
                        diagnostics,
                        build_target,
                    );
                    visited.remove(&canonical);
                    let filtered =
                        apply_only_filter(imported_decls, &only, &path, span, diagnostics);
                    result.extend(filtered);
                    continue;
                }
                diagnostics.push(
                    Diagnostic::error(
                        "`use` requires a file path context — not supported in inline code",
                    )
                    .with_code("ILO-P017")
                    .with_span(span, "here"),
                );
                continue;
            };

            let file_path = dir.join(&path);
            let canonical = match file_path.canonicalize() {
                Ok(c) => c,
                Err(_) => {
                    diagnostics.push(
                        Diagnostic::error(format!("use \"{}\": file not found", path))
                            .with_code("ILO-P017")
                            .with_span(span, "imported here"),
                    );
                    continue;
                }
            };

            if visited.contains(&canonical) {
                diagnostics.push(
                    Diagnostic::error(format!("use \"{}\": circular import", path))
                        .with_code("ILO-P018")
                        .with_span(span, "imported here"),
                );
                continue;
            }

            let source = match std::fs::read_to_string(&canonical) {
                Ok(s) => s,
                Err(e) => {
                    diagnostics.push(
                        Diagnostic::error(format!("use \"{}\": {}", path, e))
                            .with_code("ILO-P017")
                            .with_span(span, "imported here"),
                    );
                    continue;
                }
            };

            let tokens = match lexer::lex(&source) {
                Ok(t) => t,
                Err(e) => {
                    diagnostics.push(Diagnostic::from(&e));
                    continue;
                }
            };

            let token_spans: Vec<(lexer::Token, ast::Span)> = tokens
                .into_iter()
                .map(|(t, r)| {
                    (
                        t,
                        ast::Span {
                            start: r.start,
                            end: r.end,
                        },
                    )
                })
                .collect();

            let (mut imported_prog, parse_errors) = parser::parse(token_spans);
            ast::resolve_aliases(&mut imported_prog);
            ast::desugar_dot_var_index(&mut imported_prog);
            for e in &parse_errors {
                diagnostics.push(Diagnostic::from(e));
            }

            visited.insert(canonical.clone());
            let imported_dir = canonical.parent();
            let (imported_decls, imported_exported) = resolve_imports_inner(
                imported_prog.declarations,
                imported_dir,
                visited,
                diagnostics,
                build_target,
                true,
            );
            visited.remove(&canonical);

            // Apply import filter based on form:
            //
            // - Flat (`use "path"`): public declarations (those in `imported_exported`) come
            //   through. Private (`_`-prefixed) names and non-re-exported transitive imports
            //   are excluded. (Legacy behaviour for pre-re-export files: if no re-export
            //   annotations exist in the imported file, `imported_exported` equals all own
            //   non-`_` decls, which is the same as before.)
            //
            // - Selective (`use "path" [name1 name2]`): only the listed names are imported,
            //   subject to the same export-surface constraint — each requested name must be
            //   in the imported file's public surface. `_`-prefixed names are always blocked.
            //
            // - Named-module (`use alias:"path"`): all public (non-`_`) names in the export
            //   surface are imported and prefixed with `alias-`.
            //
            // - Re-export (`use re:"path" [name1 name2]`): same as selective import, but the
            //   imported names are added to *this* module's export surface so consumers can
            //   further import them.
            let filtered = if let Some(ref names) = only {
                // Selective / re-export form — block private names and enforce export surface
                for name in names {
                    if name.starts_with('_') {
                        diagnostics.push(
                            Diagnostic::error(format!(
                                "use \"{}\": '{}' is module-private (names starting with `_` \
                                 are not exported)",
                                path, name
                            ))
                            .with_code("ILO-P019")
                            .with_span(span, "imported here"),
                        );
                        continue;
                    }
                    // Check the name is in the imported module's export surface
                    let found = imported_exported.iter().any(|e| e == name)
                        || imported_decls
                            .iter()
                            .any(|d| decl_name(d) == Some(name.as_str()));
                    if !found {
                        diagnostics.push(
                            Diagnostic::error(format!(
                                "use \"{}\": name '{}' not found in imported file",
                                path, name
                            ))
                            .with_code("ILO-P019")
                            .with_span(span, "imported here"),
                        );
                    }
                }
                let selected = imported_decls
                    .into_iter()
                    .filter(|d| {
                        decl_name(d)
                            .map(|n| !n.starts_with('_') && names.iter().any(|s| s == n))
                            .unwrap_or(false)
                    })
                    .collect::<Vec<_>>();
                // If this is a re-export, add selected names to this module's export surface
                if reexport {
                    for name in names {
                        if !name.starts_with('_') {
                            exported_names.insert(name.clone());
                        }
                    }
                }
                selected
            } else if let Some(ref pfx) = alias {
                // Named-module form: strip private, then rename public to `alias-name`.
                let public_decls: Vec<ast::Decl> = imported_decls
                    .into_iter()
                    .filter(|d| decl_name(d).map(|n| !n.starts_with('_')).unwrap_or(true))
                    .collect();
                apply_module_alias(public_decls, pfx)
            } else {
                // Flat import: everything (including private helpers) comes through.
                // Preserves backward-compatible behaviour — all transitively imported
                // declarations are visible in the importing file's scope.
                imported_decls
            };

            // Prepend imported declarations (so they appear before the importer's own decls)
            result.extend(filtered);
        } else {
            // Own declaration: add to result and mark as exported (if public)
            if let Some(name) = decl_name(&decl) {
                if !name.starts_with('_') {
                    exported_names.insert(name.to_string());
                }
            }
            result.push(decl);
        }
    }

    (result, exported_names.into_iter().collect())
}

/// Return `true` if any `Expr::Call` or `Expr::Ref` in `decls` has a name
/// that starts with `prefix`. Used by the lazy-import gate to decide whether
/// a deferred module is actually needed.
fn decls_reference_prefix(decls: &[ast::Decl], prefix: &str) -> bool {
    fn expr_refs(expr: &ast::Expr, prefix: &str) -> bool {
        match expr {
            ast::Expr::Call { function, args, .. } => {
                if function.starts_with(prefix) {
                    return true;
                }
                args.iter().any(|a| expr_refs(a, prefix))
            }
            ast::Expr::Ref(name) => name.starts_with(prefix),
            ast::Expr::BinOp { left, right, .. } => {
                expr_refs(left, prefix) || expr_refs(right, prefix)
            }
            ast::Expr::UnaryOp { operand, .. } => expr_refs(operand, prefix),
            ast::Expr::Ok(inner) | ast::Expr::Err(inner) => expr_refs(inner, prefix),
            ast::Expr::List(items) => items.iter().any(|e| expr_refs(e, prefix)),
            ast::Expr::Record { fields, .. } => fields.iter().any(|(_, e)| expr_refs(e, prefix)),
            ast::Expr::Field { object, .. } => expr_refs(object, prefix),
            ast::Expr::Index { object, .. } => expr_refs(object, prefix),
            ast::Expr::Match { subject, arms } => {
                subject
                    .as_deref()
                    .map(|s| expr_refs(s, prefix))
                    .unwrap_or(false)
                    || arms
                        .iter()
                        .any(|arm| arm.body.iter().any(|s| stmt_refs(&s.node, prefix)))
            }
            ast::Expr::NilCoalesce { value, default } => {
                expr_refs(value, prefix) || expr_refs(default, prefix)
            }
            ast::Expr::With { object, updates } => {
                expr_refs(object, prefix) || updates.iter().any(|(_, e)| expr_refs(e, prefix))
            }
            ast::Expr::Ternary {
                condition,
                then_expr,
                else_expr,
            } => {
                expr_refs(condition, prefix)
                    || expr_refs(then_expr, prefix)
                    || expr_refs(else_expr, prefix)
            }
            ast::Expr::MakeClosure { captures, .. } => {
                captures.iter().any(|e| expr_refs(e, prefix))
            }
            ast::Expr::AnonRecord { fields, .. } => {
                fields.iter().any(|(_, e)| expr_refs(e, prefix))
            }
            ast::Expr::Literal(_) | ast::Expr::Todo(_) | ast::Expr::Panic(_) => false,
        }
    }

    fn stmt_refs(stmt: &ast::Stmt, prefix: &str) -> bool {
        match stmt {
            ast::Stmt::Let { value, .. } | ast::Stmt::Destructure { value, .. } => {
                expr_refs(value, prefix)
            }
            ast::Stmt::Expr(e) | ast::Stmt::Return(e) => expr_refs(e, prefix),
            ast::Stmt::Break(Some(e)) => expr_refs(e, prefix),
            ast::Stmt::Break(None) | ast::Stmt::Continue => false,
            ast::Stmt::Guard {
                condition,
                body,
                else_body,
                ..
            } => {
                expr_refs(condition, prefix)
                    || body.iter().any(|s| stmt_refs(&s.node, prefix))
                    || else_body
                        .as_deref()
                        .map(|b| b.iter().any(|s| stmt_refs(&s.node, prefix)))
                        .unwrap_or(false)
            }
            ast::Stmt::Match { subject, arms } => {
                subject
                    .as_ref()
                    .map(|s| expr_refs(s, prefix))
                    .unwrap_or(false)
                    || arms
                        .iter()
                        .any(|arm| arm.body.iter().any(|s| stmt_refs(&s.node, prefix)))
            }
            ast::Stmt::ForEach {
                collection, body, ..
            } => expr_refs(collection, prefix) || body.iter().any(|s| stmt_refs(&s.node, prefix)),
            ast::Stmt::ForRange {
                start, end, body, ..
            } => {
                expr_refs(start, prefix)
                    || expr_refs(end, prefix)
                    || body.iter().any(|s| stmt_refs(&s.node, prefix))
            }
            ast::Stmt::While { condition, body } => {
                expr_refs(condition, prefix) || body.iter().any(|s| stmt_refs(&s.node, prefix))
            }
            ast::Stmt::Defer { expr, .. } => expr_refs(expr, prefix),
        }
    }

    for decl in decls {
        let referenced = match decl {
            ast::Decl::Function { body, .. } => body.iter().any(|s| stmt_refs(&s.node, prefix)),
            ast::Decl::Tool { .. }
            | ast::Decl::TypeDef { .. }
            | ast::Decl::SumType { .. }
            | ast::Decl::Alias { .. }
            | ast::Decl::Use { .. }
            | ast::Decl::Error { .. } => false,
        };
        if referenced {
            return true;
        }
    }
    false
}

/// Rename all named declarations in `decls` by prepending `alias-` to their name.
/// Used by the `use alias:"path"` named-module import form.
fn apply_module_alias(decls: Vec<ast::Decl>, alias: &str) -> Vec<ast::Decl> {
    decls
        .into_iter()
        .map(|d| rename_decl_with_alias(d, alias))
        .collect()
}

/// Return a copy of `decl` with its name prefixed by `alias-`.
/// Declarations without a name (errors, `Use` nodes) pass through unchanged.
fn rename_decl_with_alias(decl: ast::Decl, alias: &str) -> ast::Decl {
    match decl {
        ast::Decl::Function {
            name,
            params,
            return_type,
            body,
            span,
            type_params,
            effect_set,
        } => ast::Decl::Function {
            name: format!("{}-{}", alias, name),
            params,
            return_type,
            body,
            span,
            type_params,
            effect_set,
        },
        ast::Decl::Tool {
            name,
            description,
            params,
            return_type,
            timeout,
            retry,
            span,
        } => ast::Decl::Tool {
            name: format!("{}-{}", alias, name),
            description,
            params,
            return_type,
            timeout,
            retry,
            span,
        },
        ast::Decl::TypeDef { name, fields, span } => ast::Decl::TypeDef {
            name: format!("{}-{}", alias, name),
            fields,
            span,
        },
        ast::Decl::Alias { name, target, span } => ast::Decl::Alias {
            name: format!("{}-{}", alias, name),
            target,
            span,
        },
        // Use and Error nodes have no name — pass through unchanged
        other => other,
    }
}

fn report_diagnostic(d: &Diagnostic, mode: OutputMode) {
    let s = match mode {
        OutputMode::Ansi => AnsiRenderer { use_color: true }.render(d),
        OutputMode::Text => AnsiRenderer { use_color: false }.render(d),
        // JSON mode: one object per line (NDJSON) so multiple errors are parseable.
        OutputMode::Json => format!("{}\n", json::render(d)),
    };
    eprint!("{}", s);
}

/// Load a single env file into the process environment.
/// Lines starting with `#` are comments. Blank lines are skipped.
/// Format: `KEY=VALUE` — no quoting, no variable expansion.
/// Does NOT overwrite variables already set in the environment.
fn load_env_file(path: &str) {
    let Ok(contents) = std::fs::read_to_string(path) else {
        return;
    };
    for line in contents.lines() {
        let line = line.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        if let Some((key, val)) = line.split_once('=') {
            let key = key.trim();
            let val = val.trim();
            if !key.is_empty() && std::env::var(key).is_err() {
                // SAFETY: single-threaded at startup, no concurrent env access
                unsafe { std::env::set_var(key, val) };
            }
        }
    }
}

/// Load `.env.local` then `.env` from the current working directory.
/// `.env.local` takes priority (loaded first; later files don't overwrite).
fn load_dotenv() {
    load_env_file(".env.local");
    load_env_file(".env");
}

/// Install the production-safety guards for an `ilo run`. Reads
/// `--max-runtime` / `--max-output-bytes` off the global flags (with the
/// defaults from `runtime_guard`) and arms the watchdog plus the output
/// counter. Called from both the explicit `Cmd::Run` arm and the bare
/// positional dispatch — both ultimately execute user code.
///
/// A mandelbrot persona run (2026-05-20) missed a `col=col+1` loop
/// increment, produced 165 MB of stdout in an infinite loop before the
/// harness killed it, and the agent had no useful signal to learn from.
/// This installs the cap so the next runaway aborts with `ILO-R016` /
/// `ILO-R017` and a hint pointing at the cause.
fn install_runtime_guard(global: &cli::Global, mode: OutputMode) {
    let secs = global
        .max_runtime
        .unwrap_or(ilo::runtime_guard::DEFAULT_MAX_RUNTIME_SECS);
    let bytes = global
        .max_output_bytes
        .unwrap_or(ilo::runtime_guard::DEFAULT_MAX_OUTPUT_BYTES);
    let abort_mode = if matches!(mode, OutputMode::Json) {
        ilo::runtime_guard::AbortMode::Json
    } else {
        ilo::runtime_guard::AbortMode::Text
    };
    ilo::runtime_guard::install(std::time::Duration::from_secs(secs), bytes, abort_mode);
}

fn main() {
    load_dotenv();

    let mut raw_args: Vec<String> = std::env::args().collect();

    // `--max-ast-depth N` is a global flag (see ILO-P103). Strip it from
    // `raw_args` here, before either the clap or the bare-positional dispatch
    // sees the value, and install it on the parser as a process-wide override.
    // Threading the cap through every `parser::parse` call site would touch 30+
    // sites for no behavioural win — every parse in the process is started
    // from the same `fn main`, so a single atomic is enough.
    let mut i = 1;
    while i < raw_args.len() {
        // Stop scanning at `--` so a literal positional `--max-ast-depth` arg
        // to a user program isn't intercepted.
        if raw_args[i] == "--" {
            break;
        }
        if raw_args[i] == "--max-ast-depth" {
            if i + 1 >= raw_args.len() {
                eprintln!("error: --max-ast-depth requires a value");
                std::process::exit(1);
            }
            match raw_args[i + 1].parse::<usize>() {
                Ok(n) if n >= 1 => parser::set_max_ast_depth_override(n),
                _ => {
                    eprintln!(
                        "error: --max-ast-depth requires a positive integer, got '{}'",
                        raw_args[i + 1]
                    );
                    std::process::exit(1);
                }
            }
            raw_args.drain(i..i + 2);
            continue;
        }
        if let Some(rest) = raw_args[i].strip_prefix("--max-ast-depth=") {
            match rest.parse::<usize>() {
                Ok(n) if n >= 1 => parser::set_max_ast_depth_override(n),
                _ => {
                    eprintln!("error: --max-ast-depth requires a positive integer, got '{rest}'");
                    std::process::exit(1);
                }
            }
            raw_args.remove(i);
            continue;
        }
        i += 1;
    }

    // Global deprecation nudge: if any arg is the old `--run-vm` spelling,
    // emit the one-shot hint here so it fires uniformly across every
    // dispatch path (bare positional, `ilo run` subcommand, clap-driven
    // visible_alias resolution). The pre-parse scans in
    // `extract_run_engine_flag` and `dispatch_bare_args` also call the
    // emitter; the AtomicBool guard inside ensures at most one line per
    // process even when multiple paths see the alias. Stop the `--`
    // separator from triggering the hint on literal data.
    {
        let mut hit = false;
        for a in raw_args.iter().skip(1) {
            if a == "--" {
                break;
            }
            if a == "--run-vm" {
                hit = true;
                break;
            }
        }
        if hit {
            emit_run_vm_alias_hint();
        }
    }

    // Special-case: `ilo -ai` (hidden alias for compact spec)
    if raw_args.get(1).map(|s| s.as_str()) == Some("-ai") {
        print!("{}", compact_spec());
        std::process::exit(0);
    }

    // `ilo build --help` / `ilo build -h`: print the manifesto-strict build
    // help and exit 0 before clap or the unknown-flag guard sees it.
    if raw_args.get(1).map(|s| s.as_str()) == Some("build")
        && raw_args.iter().skip(2).any(|a| a == "--help" || a == "-h")
    {
        print_build_help();
        std::process::exit(0);
    }

    // Friendly usage for `ilo run` / `ilo check` / `ilo build` with no
    // source argument. Without this, clap rejects the missing-positional
    // and we fall through to dispatch_bare_args, which then tries to lex
    // the verb (`run` / `check` / `build`) as inline ilo source and emits
    // a confusing parser error. The verb-noun shape is the recommended
    // surface for agents and humans alike (ilo run file.ilo); show usage
    // instead of a parser blowup.
    if raw_args.len() == 2 {
        match raw_args[1].as_str() {
            "run" => {
                eprintln!("Usage: ilo run <file.@> [func] [args...]");
                eprintln!("       ilo run <inline-code> [func] [args...]");
                std::process::exit(1);
            }
            "check" => {
                eprintln!("Usage: ilo check <file.@>");
                eprintln!("       ilo check <inline-code>");
                eprintln!("       ilo check <file.@> --json   (machine-readable diagnostics)");
                std::process::exit(1);
            }
            "build" => {
                print_build_help();
                std::process::exit(1);
            }
            "trace" => {
                eprintln!("Usage: ilo trace <file.ilo> [func] [args...]");
                std::process::exit(1);
            }
            // `ilo test` with no path arg is valid (defaults to `examples/`)
            // and is handled in the runner; no usage stub needed here.
            _ => {}
        }
    }

    // Try clap parse.  When it fails (e.g. `ilo 'fn x:n>n;*x 2' 5` or
    // `ilo --help`), reconstruct a Cli with the raw positional args.
    let (cli, bare_args_have_bin_name) = match cli::Cli::try_parse_from(&raw_args) {
        Ok(c) => (c, false),
        Err(_) => {
            // Build a Cli whose `cmd` is None and `args` carries the raw argv
            // (including the binary name at position 0).
            (
                cli::Cli {
                    cmd: None,
                    global: cli::Global {
                        ansi: false,
                        text: false,
                        json: false,
                        no_hints: false,
                        silent: false,
                        max_ast_depth: None,
                        max_runtime: None,
                        max_output_bytes: None,
                    },
                    args: raw_args,
                },
                true,
            )
        }
    };

    let code = dispatch_cli(cli, bare_args_have_bin_name);
    if code != 0 {
        std::process::exit(code);
    }
}

/// Top-level dispatch: returns the process exit code (0 = success).
/// `bare_has_bin` is true when the `None` arm's args already include argv[0] (binary name).
fn dispatch_cli(cli: cli::Cli, bare_has_bin: bool) -> i32 {
    match cli.cmd {
        Some(cli::Cmd::Tools(t)) => {
            let mut args: Vec<String> = Vec::new();
            if let Some(ref p) = t.mcp_path {
                args.push("--mcp".into());
                args.push(p.clone());
            }
            if let Some(ref p) = t.tools_path {
                args.push("--tools".into());
                args.push(p.clone());
            }
            if t.human {
                args.push("--human".into());
            }
            if t.ilo {
                args.push("--ilo".into());
            }
            if t.json {
                args.push("--json".into());
            }
            if t.full {
                args.push("--full".into());
            }
            if t.graph {
                args.push("--graph".into());
            }
            tools_cmd(&args)
        }
        Some(cli::Cmd::Graph(g)) => {
            let mut args: Vec<String> = vec![g.file];
            if let Some(ref n) = g.fn_name {
                args.push("--fn".into());
                args.push(n.clone());
            }
            if g.reverse {
                args.push("--reverse".into());
            }
            if g.subgraph {
                args.push("--subgraph".into());
            }
            if let Some(b) = g.budget {
                args.push("--budget".into());
                args.push(b.to_string());
            }
            if g.dot {
                args.push("--dot".into());
            }
            graph_cmd(&args)
        }
        Some(cli::Cmd::Repl) => {
            if cli.global.json {
                serv_cmd(&["-j".to_string()]);
            } else {
                repl_cmd();
            }
            0
        }
        Some(cli::Cmd::Serv(s)) => {
            let mut args: Vec<String> = vec!["-j".into()];
            if let Some(ref p) = s.mcp_path {
                args.push("--mcp".into());
                args.push(p.clone());
            }
            if let Some(ref p) = s.tools_path {
                args.push("--tools".into());
                args.push(p.clone());
            }
            serv_cmd(&args);
            0
        }
        Some(cli::Cmd::Compile(c)) | Some(cli::Cmd::Build(c)) => {
            // Validate --target against the supported list before dispatching.
            if let Some(ref t) = c.target {
                if !cli::args::SUPPORTED_TARGETS.contains(&t.as_str()) {
                    let list = cli::args::SUPPORTED_TARGETS.join(", ");
                    eprintln!("error: unsupported target '{t}'. Supported targets: {list}");
                    return 1;
                }
            }
            let mut args: Vec<String> = vec![c.source];
            if let Some(ref o) = c.output {
                args.push("-o".into());
                args.push(o.clone());
            }
            if c.bench {
                args.push("--bench".into());
            }
            if cli.global.explicit_json() {
                args.push("--json".into());
            }
            if let Some(ref t) = c.target {
                args.push("--target".into());
                args.push(t.clone());
            }
            if let Some(ref f) = c.func {
                args.push(f.clone());
            }
            compile_cmd(&args)
        }
        Some(cli::Cmd::Check(c)) => {
            let mode = cli.global.output_mode();
            let explicit_json = cli.global.explicit_json();
            check_cmd(&c.source, mode, explicit_json, c.strict, c.show_effects)
        }
        Some(cli::Cmd::Explain(e)) => {
            let as_json = cli.global.explicit_json();
            explain_cmd(&e.code, as_json)
        }
        Some(cli::Cmd::Spec(s)) => {
            let as_json = cli.global.explicit_json();
            match s.topic.as_deref() {
                Some("lang") => {
                    if as_json {
                        let v = serde_json::json!({
                            "schemaVersion": 1,
                            "format": "markdown",
                            "content": include_str!("../SPEC.md"),
                        });
                        println!("{}", v);
                    } else {
                        print!("{}", include_str!("../SPEC.md"));
                    }
                }
                Some("ai") => {
                    if as_json {
                        // Build per-item builtins array from the canonical ALL slice.
                        let builtins_list: Vec<serde_json::Value> = ilo::builtins::Builtin::ALL
                            .iter()
                            .map(|b| {
                                serde_json::json!({
                                    "name": b.name(),
                                    "stability": b.stability(),
                                })
                            })
                            .collect();
                        let v = serde_json::json!({
                            "schemaVersion": 1,
                            "format": "ai-txt",
                            "content": compact_spec(),
                            "stability": {
                                "doc": "STABILITY.md",
                                "tiers": ["stable", "provisional", "experimental"],
                                "stable": ["schemaVersion:1", "ILO-error-codes", "serv-protocol-phases", "file-version-pragma", "manifesto-principles", "reserved-name-policy"],
                                "provisional": ["builtin-signatures", "cli-flag-names", "error-message-prose", "examples-corpus", "ilo-test-surface"],
                                "experimental": ["0.13-in-flight-features", "aot-artifact-format", "cranelift-jit-internals", "extensions-dir", "cargo-feature-flags"],
                            },
                            "builtins": builtins_list,
                        });
                        println!("{}", v);
                    } else {
                        print!("{}", compact_spec());
                    }
                }
                _ => print_help(),
            }
            0
        }
        Some(cli::Cmd::Skill(s)) => {
            let as_json = cli.global.explicit_json();
            match s.cmd {
                cli::args::SkillCmd::List => skill_list_cmd(as_json),
                cli::args::SkillCmd::Get { name } => skill_get_cmd(&name, as_json),
                cli::args::SkillCmd::Path { name } => skill_path_cmd(&name, as_json),
                cli::args::SkillCmd::Show { name } => skill_show_cmd(&name, as_json),
            }
        }
        Some(cli::Cmd::Httpd(h)) => {
            let func = h.func.as_deref().unwrap_or("handler");
            httpd_cmd(h.port, &h.handler, func)
        }
        Some(cli::Cmd::Test(t)) => cli::test_runner::run(t),
        Some(cli::Cmd::Trace(t)) => cli::trace::run(t),
        Some(cli::Cmd::Version) => version_cmd(cli.global.explicit_json()),
        Some(cli::Cmd::Add(a)) => std::process::exit(ilo::pkg::cmd_add(&a.package)),
        Some(cli::Cmd::Update(u)) => std::process::exit(ilo::pkg::cmd_update(u.package.as_deref())),
        Some(cli::Cmd::Run(r)) => {
            let mode = cli.global.output_mode();
            let explicit_json = cli.global.explicit_json();
            let no_hints = cli.global.no_hints;
            let silent = cli.global.silent;
            install_runtime_guard(&cli.global, mode);
            dispatch_run(r, mode, explicit_json, no_hints, silent)
        }
        None => {
            // No subcommand — bare positional args (e.g. `ilo 'fn x:n>n;*x 2' 5`)
            // dispatch_bare_args expects args[0] = binary name.
            let args = if bare_has_bin {
                cli.args
            } else {
                let mut full = vec!["ilo".to_string()];
                full.extend(cli.args);
                full
            };
            // Bare-positional dispatch also executes programs (the legacy
            // `ilo '<code>'` and `ilo file.ilo` shapes), so install the guard
            // here too.
            install_runtime_guard(&cli.global, cli.global.output_mode());
            dispatch_bare_args(args, &cli.global)
        }
    }
}

/// Handle bare positional args (no subcommand).
///
/// Covers: `ilo <code> [func] [args]`, `ilo <file.ilo> [func] [args]`,
/// `ilo --version`, `ilo --help`, `ilo -e <code>`, `ilo --explain <code>`,
/// and all `--run-*` / `--emit` / `--bench` / `--dense` / `--expanded` flags.
fn dispatch_bare_args(raw_args: Vec<String>, global: &cli::Global) -> i32 {
    // Strip output mode flags from raw_args (--json/-j, --text/-t, --ansi/-a, --no-hints/-n)
    let (mode, explicit_json, no_hints, silent, args) = detect_output_mode(raw_args);

    // Extract --run-* engine flags from anywhere in the arg list so users can
    // pass them before or after positional args. Examples that should be
    // equivalent:
    //   ilo 'f>n;5' --run-tree f
    //   ilo 'f>n;5' f --run-tree
    //   ilo --run-tree 'f>n;5' f
    //   ilo file.ilo --run-tree main
    //   ilo --run-tree file.ilo main
    //
    // Conflicting flags (e.g. --run-tree --run-vm) still error cleanly.
    let (pre_engine, args) = match extract_run_engine_flag(args) {
        Ok(v) => v,
        Err(msg) => {
            eprintln!("{msg}");
            return 1;
        }
    };

    // Extract --ast flag from anywhere in the arg list so it can sit before
    // the source, after the source, or after positional args. The flag
    // forces the AST-dump path; without it `ilo file.ilo` auto-runs a
    // single-function file or prints a friendly function listing.
    let (pre_ast, args) = {
        let mut found = false;
        let mut filtered: Vec<String> = Vec::with_capacity(args.len());
        for a in args.into_iter() {
            if a == "--ast" {
                found = true;
            } else {
                filtered.push(a);
            }
        }
        (found, filtered)
    };

    // Override with clap-parsed global flags if they were set
    let mode = if global.ansi {
        OutputMode::Ansi
    } else if global.text {
        OutputMode::Text
    } else if global.json {
        OutputMode::Json
    } else {
        mode
    };
    let explicit_json = explicit_json || global.explicit_json();
    let no_hints = no_hints || global.no_hints;
    let silent = silent || global.silent;

    if args.len() < 2 {
        eprintln!(
            "Usage: ilo <file-or-code> [args... | --run func args... | --bench func args...]"
        );
        eprintln!("       ilo run <file> [args...]                  Run (verb form)");
        eprintln!("       ilo check <file> [--json]                 Verify without running");
        eprintln!(
            "       ilo build <file> -o <out> [func]          AOT compile (alias for compile)"
        );
        eprintln!("       ilo repl                                  Interactive REPL");
        eprintln!("       ilo serv [--mcp <path>] [--tools <path>]  Stdio agent loop");
        eprintln!("       ilo graph <file> [--fn NAME] [--dot]      Dependency graph");
        eprintln!("       ilo compile <file> [-o out] [func]        AOT compile to binary");
        eprintln!("       ilo help | -h     Show usage and examples");
        eprintln!("       ilo help lang     Show language specification");
        eprintln!("       ilo help ai | -ai Compact spec for LLM consumption");
        eprintln!("       ilo --version | -V | -v");
        return 1;
    }

    if args[1] == "--version" || args[1] == "-V" || args[1] == "-v" {
        println!("ilo {}", env!("CARGO_PKG_VERSION"));
        return 0;
    }

    if args[1] == "--explain" {
        return match args.get(2) {
            Some(code) => match diagnostic::registry::lookup(code) {
                Some(entry) => {
                    print!("{}", entry.long);
                    0
                }
                None => {
                    eprintln!("unknown error code: {code}");
                    eprintln!("Error codes have the form ILO-L001, ILO-P001, ILO-T001, ILO-R001.");
                    1
                }
            },
            None => {
                eprintln!("Usage: ilo --explain <code>  (e.g. ilo --explain ILO-T005)");
                1
            }
        };
    }

    if args[1] == "-ai" {
        print!("{}", compact_spec());
        return 0;
    }

    if args[1] == "help" || args[1] == "--help" || args[1] == "-h" {
        if args.len() > 2 && args[2] == "lang" {
            print!("{}", include_str!("../SPEC.md"));
        } else if args.len() > 2 && args[2] == "ai" {
            print!("{}", compact_spec());
        } else {
            print_help();
        }
        return 0;
    }

    // Guard: if args[1] is an unrecognised clean long flag (e.g. `--engine`,
    // `--foo`), reject it with a clear "unrecognised flag" message instead
    // of silently treating it as inline code (which surfaces later as a
    // mystery lex error). `--version`, `--help`, `--explain`, `--ast`,
    // `--run-*`, mode flags etc. are already handled or stripped above this
    // point, so anything reaching here with `--word` shape is genuinely
    // unknown. Position-based mode flags (`--bench`, `--emit`, `--dense`,
    // `--expanded`, `--fmt`, `--fmt-expanded`, `--tools`, `--mcp`) sit at
    // args[m..] not args[1] so they're not affected by this guard. Final
    // tail validation happens in `dispatch_run` on `r.rest`.
    if let Err(msg) = cli::reject_unknown_flags(std::slice::from_ref(&args[1])) {
        eprintln!("{msg}");
        return 1;
    }

    // Determine source: file path, `-e <code>`, or inline code.
    // We pass the source *identifier* to RunArgs.source — dispatch_run handles
    // file-vs-inline detection and reading.
    let (source, mode_args_start) = if std::path::Path::new(&args[1]).is_file() {
        // Pass the file path through; dispatch_run will read it.
        (args[1].clone(), 2)
    } else if args[1] == "-e" {
        if args.len() < 3 || args[2].is_empty() {
            eprintln!("Usage: ilo <file-or-code> [args... | --run func args...]");
            return 1;
        }
        (args[2].clone(), 3)
    } else {
        if args[1].is_empty() {
            eprintln!("Error: empty code string");
            return 1;
        }
        (args[1].clone(), 2)
    };

    // Scan for --tools and --mcp flags
    let (tools_config_path, mcp_config_path, args) = {
        let mut tools_path: Option<String> = None;
        let mut mcp_path: Option<String> = None;
        let mut filtered: Vec<String> = Vec::with_capacity(args.len());
        let mut i = 0;
        while i < args.len() {
            if args[i] == "--tools" {
                if i + 1 < args.len() {
                    tools_path = Some(args[i + 1].clone());
                    i += 2;
                } else {
                    eprintln!("error: --tools requires a path argument");
                    return 1;
                }
            } else if args[i] == "--mcp" {
                if i + 1 < args.len() {
                    mcp_path = Some(args[i + 1].clone());
                    i += 2;
                } else {
                    eprintln!("error: --mcp requires a path argument");
                    return 1;
                }
            } else {
                filtered.push(args[i].clone());
                i += 1;
            }
        }
        if tools_path.is_some() && mcp_path.is_some() {
            eprintln!("error: --tools and --mcp are mutually exclusive");
            return 1;
        }
        (tools_path, mcp_path, filtered)
    };

    // Build RunArgs from positional args
    // Determine engine, emit, explain, dense, expanded, bench flags from remaining args
    let m = mode_args_start;
    let (engine_flag, run_rest_start) = if args.len() > m {
        match args[m].as_str() {
            "--jit" => (Some(cli::Engine::Cranelift), m + 1),
            "--run-llvm" => (Some(cli::Engine::Llvm), m + 1),
            "--vm" => (Some(cli::Engine::Vm), m + 1),
            "--run-vm" => {
                emit_run_vm_alias_hint();
                (Some(cli::Engine::Vm), m + 1)
            }
            _ => (None, m),
        }
    } else {
        (None, m)
    };

    // Merge in any --run-* flag extracted from a non-canonical position
    // (before the source, or after positional func/args).
    let engine_flag = engine_flag.or(pre_engine);

    // Check for mode flags at the start of remaining args
    if args.len() > m {
        match args[m].as_str() {
            "--bench" => {
                let run_args = cli::RunArgs {
                    source,
                    engine: cli::Engine::Default,
                    run_vm: false,
                    jit: false,
                    run_llvm: false,
                    bench: true,
                    emit: None,
                    explain: false,
                    dense: false,
                    expanded: false,
                    ast: false,
                    tools_path: tools_config_path,
                    mcp_path: mcp_config_path,
                    allow_net: None,
                    allow_read: None,
                    allow_write: None,
                    allow_run: None,
                    allow_env: None,
                    rest: args[m + 1..].to_vec(),
                };
                return dispatch_run(run_args, mode, explicit_json, no_hints, silent);
            }
            "--explain" | "-x" if engine_flag.is_none() => {
                let run_args = cli::RunArgs {
                    source,
                    engine: cli::Engine::Default,
                    run_vm: false,
                    jit: false,
                    run_llvm: false,
                    bench: false,
                    emit: None,
                    explain: true,
                    dense: false,
                    expanded: false,
                    ast: false,
                    tools_path: tools_config_path,
                    mcp_path: mcp_config_path,
                    allow_net: None,
                    allow_read: None,
                    allow_write: None,
                    allow_run: None,
                    allow_env: None,
                    rest: vec![],
                };
                return dispatch_run(run_args, mode, explicit_json, no_hints, silent);
            }
            "--emit" if engine_flag.is_none() => {
                let target = if args.len() > m + 1 {
                    Some(args[m + 1].clone())
                } else {
                    None
                };
                let run_args = cli::RunArgs {
                    source,
                    engine: cli::Engine::Default,
                    run_vm: false,
                    jit: false,
                    run_llvm: false,
                    bench: false,
                    emit: target,
                    explain: false,
                    dense: false,
                    expanded: false,
                    ast: false,
                    tools_path: tools_config_path,
                    mcp_path: mcp_config_path,
                    allow_net: None,
                    allow_read: None,
                    allow_write: None,
                    allow_run: None,
                    allow_env: None,
                    rest: vec![],
                };
                return dispatch_run(run_args, mode, explicit_json, no_hints, silent);
            }
            "--dense" | "-d" | "--fmt" if engine_flag.is_none() => {
                let run_args = cli::RunArgs {
                    source,
                    engine: cli::Engine::Default,
                    run_vm: false,
                    jit: false,
                    run_llvm: false,
                    bench: false,
                    emit: None,
                    explain: false,
                    dense: true,
                    expanded: false,
                    ast: false,
                    tools_path: tools_config_path,
                    mcp_path: mcp_config_path,
                    allow_net: None,
                    allow_read: None,
                    allow_write: None,
                    allow_run: None,
                    allow_env: None,
                    rest: vec![],
                };
                return dispatch_run(run_args, mode, explicit_json, no_hints, silent);
            }
            "--expanded" | "-e" | "--fmt-expanded" if engine_flag.is_none() => {
                let run_args = cli::RunArgs {
                    source,
                    engine: cli::Engine::Default,
                    run_vm: false,
                    jit: false,
                    run_llvm: false,
                    bench: false,
                    emit: None,
                    explain: false,
                    dense: false,
                    expanded: true,
                    ast: false,
                    tools_path: tools_config_path,
                    mcp_path: mcp_config_path,
                    allow_net: None,
                    allow_read: None,
                    allow_write: None,
                    allow_run: None,
                    allow_env: None,
                    rest: vec![],
                };
                return dispatch_run(run_args, mode, explicit_json, no_hints, silent);
            }
            _ => {}
        }
    }

    // Default: build RunArgs with engine and remaining positional args
    let engine = engine_flag.unwrap_or(cli::Engine::Default);
    let rest_start = if engine_flag.is_some() {
        run_rest_start
    } else {
        m
    };
    let rest: Vec<String> = args[rest_start..].to_vec();

    let run_args = cli::RunArgs {
        source,
        engine,
        run_vm: false,
        jit: false,
        run_llvm: false,
        bench: false,
        emit: None,
        explain: false,
        dense: false,
        expanded: false,
        ast: pre_ast,
        tools_path: tools_config_path,
        mcp_path: mcp_config_path,
        allow_net: None,
        allow_read: None,
        allow_write: None,
        allow_run: None,
        allow_env: None,
        rest,
    };
    dispatch_run(run_args, mode, explicit_json, no_hints, silent)
}

/// Resolve the function name + remaining args for an explicit engine flag
/// (`--run-tree`, `--run-vm`, `--jit`).
///
/// Mirrors the auto-pick-main heuristic from the Default engine branch
/// (PR #307): when no positional func arg is supplied, prefer a function
/// called `main` so multi-fn files don't surface as misleading arity
/// errors (Tree), silent `nil` results (VM), or bare
/// "Cranelift JIT: compilation failed" strings (Cranelift). Reported by
/// the ml-engineer / routing-tsp / devops-sre / html-scraper personas in
/// rerun6 P1.
///
/// Synthetic `__lit_N` decls emitted by inline-lambda lifting are
/// filtered out — same convention as the Default branch — so they
/// never become a default entry point.
///
/// Scope is deliberately narrow: only the no-positional case gets the
/// auto-pick treatment. When `rest` has any positional, we preserve
/// the long-standing "first arg is the func name" contract verbatim —
/// the engine then errors with `undefined function: <name>` if the
/// caller mistyped a subcommand (pinned by
/// `tests/cli_integration.rs::cli_cov_run_vm_fn_not_found` and
/// friends). Tightening that pass-through is a separate, larger
/// follow-up; this change is the minimal fix for the rerun6 P1 repro.
fn resolve_engine_func_name<'a>(
    program: &ast::Program,
    rest: &'a [String],
) -> (Option<&'a str>, &'a [String]) {
    let has_main = program.declarations.iter().any(|d| {
        matches!(
            d,
            ast::Decl::Function { name, .. } if !name.starts_with("__") && name == "main"
        )
    });

    if let Some(first) = rest.first() {
        // Mirror the default-engine non-ident-positional -> main heuristic
        // (PR #328 / src/main.rs ~2838). If the first positional does NOT
        // look like a subcommand name (e.g. `paper.txt`, `/tmp/x.json`, `42`)
        // and the program defines `main`, route to `main` and pass the whole
        // `rest` slice through as call args. Without this, the engine sees
        // `paper.txt` as a function name and emits `ILO-R002: undefined
        // function: paper.txt` while the default engine on the same
        // invocation runs `main` correctly.
        //
        // Ident-shaped first positionals are still treated as the function
        // name, so typo detection ("undefined function: helpr") and explicit
        // routing (`--run-tree file.ilo main path`) are preserved verbatim.
        //
        // Originating reports: pdf-analyst rerun7 P2 (assessment doc line
        // 6736), devops-sre rerun7 P2 (line 7009), qa-tester rerun7 P2
        // (line 6961, inline variant).
        if has_main && !looks_like_subcommand_name(first) {
            return (Some("main"), rest);
        }
        return (Some(first.as_str()), &rest[1..]);
    }

    if has_main {
        return (Some("main"), &[][..]);
    }
    (None, &[][..])
}

/// `ilo check <file-or-code>` — run the verifier without executing.
///
/// Exit code 0 = program is well-typed and verifier-clean.
/// Exit code 1 = parse / lex / import / verify errors. Diagnostics are
/// emitted to stderr in the resolved output mode (auto-detected ANSI/text,
/// or JSON when `--json` is passed or stderr is not a TTY).
///
/// Mirrors the front-half of `dispatch_run` — lex, parse, import-resolve,
/// verify — but stops before bytecode compilation / execution. Factored
/// out rather than reused so a future verify-only invocation path
/// (e.g. an `--check-only` flag on `run`) can call into the same logic
/// without disturbing the run hot path.
fn check_cmd(
    source_arg: &str,
    mode: OutputMode,
    _explicit_json: bool,
    strict: bool,
    show_effects: bool,
) -> i32 {
    // Read source from file or treat as inline code.
    let (source, is_file) = if std::path::Path::new(source_arg).is_file() {
        maybe_warn_ilo_ext(source_arg);
        match std::fs::read_to_string(source_arg) {
            Ok(s) => (s, true),
            Err(e) => {
                eprintln!("Error reading {}: {}", source_arg, e);
                return 1;
            }
        }
    } else {
        if source_arg.is_empty() {
            eprintln!("Error: empty code string");
            return 1;
        }
        (source_arg.to_string(), false)
    };

    // File path to embed in fix_plan.path so agents know which file to edit.
    // Absent for inline code (e.g. `ilo check 'f>n;5'`).
    let diag_path: Option<String> = if is_file {
        Some(source_arg.to_string())
    } else {
        None
    };

    // Enriches a diagnostic with source, optional file path, and a derived
    // fix_plan for codes that support mechanical edits (ILO-T004, ILO-T003,
    // ILO-T032, ILO-L002).
    let enrich = |d: Diagnostic| -> Diagnostic {
        let mut d = d.with_source(source.clone());
        if let Some(p) = &diag_path {
            d = d.with_path(p.clone());
        }
        d.derive_fix_plan()
    };

    let mut had_errors = false;
    // In --strict mode, any warning bumps the exit code to 1 too. Tracked
    // separately so we don't conflate genuine errors with elevated warnings
    // in any future diagnostic count or summary line.
    let mut had_warnings = false;

    let tokens = match lexer::lex(&source) {
        Ok(t) => t,
        Err(e) => {
            report_diagnostic(&enrich(Diagnostic::from(&e)), mode);
            return 1;
        }
    };

    let token_spans: Vec<(lexer::Token, ast::Span)> = tokens
        .into_iter()
        .map(|(t, r)| {
            (
                t,
                ast::Span {
                    start: r.start,
                    end: r.end,
                },
            )
        })
        .collect();

    let (mut program, parse_errors) = parser::parse(token_spans);
    ast::resolve_aliases(&mut program);
    ast::desugar_dot_var_index(&mut program);
    program.source = Some(source.clone());

    // Resolve imports relative to the file's parent dir (skipped for inline).
    {
        let base_dir: Option<std::path::PathBuf> = if is_file {
            std::path::Path::new(source_arg)
                .canonicalize()
                .ok()
                .and_then(|p| p.parent().map(|d| d.to_path_buf()))
        } else {
            None
        };
        let mut import_diagnostics: Vec<Diagnostic> = Vec::new();
        let mut visited = std::collections::HashSet::new();
        if let Ok(canonical_file) = std::path::Path::new(source_arg).canonicalize() {
            visited.insert(canonical_file);
        }
        program.declarations = resolve_imports(
            program.declarations,
            base_dir.as_deref(),
            &mut visited,
            &mut import_diagnostics,
            BuildTarget::default(),
        );
        for d in import_diagnostics {
            report_diagnostic(&d, mode);
            had_errors = true;
        }
    }

    for e in &parse_errors {
        report_diagnostic(&enrich(Diagnostic::from(e)), mode);
        had_errors = true;
    }

    // Run the verifier even when parse errors fired — diagnostics are
    // cumulative so the caller sees every issue in one pass, not a
    // fix-one-rerun-find-next loop. Verifier itself is robust to
    // partially-broken ASTs.
    let verify_result = verify::verify_with_effects(&program, show_effects);
    for w in &verify_result.warnings {
        report_diagnostic(&enrich(Diagnostic::from(w)), mode);
        had_warnings = true;
    }
    if !verify_result.errors.is_empty() {
        for e in &verify_result.errors {
            report_diagnostic(&enrich(Diagnostic::from(e)), mode);
        }
        had_errors = true;
    }

    // Print effect sets when --show-effects is requested.
    if show_effects && !verify_result.effects.is_empty() {
        println!("Effect sets:");
        for fx in &verify_result.effects {
            let declared_str = match &fx.declared {
                None => String::new(),
                Some(v) if v.is_empty() => " (declared: ^)".to_string(),
                Some(v) => format!(" (declared: ^{})", v.join("|")),
            };
            let inferred_str = if fx.inferred.is_empty() {
                "none".to_string()
            } else {
                fx.inferred.join("|")
            };
            println!("  {}: {}{}", fx.name, inferred_str, declared_str);
        }
    }

    if had_errors || (strict && had_warnings) {
        1
    } else {
        0
    }
}

/// Build a `Caps` from the `--allow-*` flags on a `RunArgs`.
///
/// If none of the flags are present, returns `Caps::Permissive` (backwards-compatible
/// unrestricted mode). As soon as any `--allow-*` flag is set, the policy
/// switches to `Caps::Restricted` and only explicitly permitted targets are
/// allowed.
fn build_caps(r: &cli::RunArgs) -> Arc<Caps> {
    let any = r.allow_net.is_some()
        || r.allow_read.is_some()
        || r.allow_write.is_some()
        || r.allow_run.is_some()
        || r.allow_env.is_some();
    if !any {
        return Arc::new(Caps::Permissive);
    }
    Arc::new(Caps::Restricted {
        net: r
            .allow_net
            .as_deref()
            .map(Caps::parse_allow)
            .unwrap_or(Policy::All),
        read: r
            .allow_read
            .as_deref()
            .map(Caps::parse_allow)
            .unwrap_or(Policy::All),
        write: r
            .allow_write
            .as_deref()
            .map(Caps::parse_allow)
            .unwrap_or(Policy::All),
        run: r
            .allow_run
            .as_deref()
            .map(Caps::parse_allow)
            .unwrap_or(Policy::All),
        env: r
            .allow_env
            .as_deref()
            .map(Caps::parse_allow)
            .unwrap_or(Policy::All),
    })
}

/// Dispatch the `run` subcommand via parsed RunArgs.  Returns exit code.
fn dispatch_run(
    r: cli::RunArgs,
    mode: OutputMode,
    explicit_json: bool,
    no_hints: bool,
    silent: bool,
) -> i32 {
    // Reject unknown `--flag` tokens in the positional tail. `RunArgs::rest`
    // uses trailing_var_arg + allow_hyphen_values so clap collects any
    // unrecognised long flag as positional; without this guard
    // `ilo main.ilo --engine tree` silently runs main with two extra
    // args and surfaces as misleading ILO-R012/ILO-R004. Use `--` to pass
    // a literal hyphen-prefixed arg: `ilo main.ilo -- --foo`.
    if let Err(msg) = cli::reject_unknown_flags(&r.rest) {
        eprintln!("{msg}");
        return 1;
    }

    // Consume the first `--` separator (if present). It exists only to
    // disambiguate hyphen-prefixed literal args from flags; it's not data
    // itself, so it must not reach the program as a positional arg.
    let mut r = r;
    if let Some(idx) = r.rest.iter().position(|s| s == "--") {
        r.rest.remove(idx);
    }

    // Build capability policy from --allow-* flags.
    let caps = build_caps(&r);

    let source_arg = &r.source;

    // Read source from file or treat as inline code
    let (source, is_file) = if std::path::Path::new(source_arg).is_file() {
        maybe_warn_ilo_ext(source_arg);
        let s = match std::fs::read_to_string(source_arg) {
            Ok(s) => s,
            Err(e) => {
                eprintln!("Error reading {}: {}", source_arg, e);
                return 1;
            }
        };
        (s, true)
    } else {
        if source_arg.is_empty() {
            eprintln!("Error: empty code string");
            return 1;
        }
        (source_arg.clone(), false)
    };

    let tools_config_path = r.tools_path.clone();
    let mcp_config_path = r.mcp_path.clone();

    if tools_config_path.is_some() && mcp_config_path.is_some() {
        eprintln!("error: --tools and --mcp are mutually exclusive");
        return 1;
    }

    warn_cross_language_syntax(&source, mode);

    let tokens = match lexer::lex(&source) {
        Ok(t) => t,
        Err(e) => {
            report_diagnostic(&Diagnostic::from(&e).with_source(source.clone()), mode);
            return 1;
        }
    };

    let token_spans: Vec<(lexer::Token, ast::Span)> = tokens
        .into_iter()
        .map(|(t, r)| {
            (
                t,
                ast::Span {
                    start: r.start,
                    end: r.end,
                },
            )
        })
        .collect();

    let (mut program, parse_errors) = parser::parse(token_spans);
    ast::resolve_aliases(&mut program);
    ast::desugar_dot_var_index(&mut program);
    program.source = Some(source.clone());

    // MCP injection
    #[cfg(not(feature = "tools"))]
    if mcp_config_path.is_some() {
        eprintln!(
            "error: --mcp requires the 'tools' feature (build with: cargo build --features tools)"
        );
        return 1;
    }

    #[cfg(feature = "tools")]
    let mut mcp_rt: Option<tokio::runtime::Runtime> = None;
    #[cfg(feature = "tools")]
    let mut mcp_provider_holder: Option<tools::mcp_provider::McpProvider> = None;

    #[cfg(feature = "tools")]
    if let Some(ref path) = mcp_config_path {
        let config = match tools::mcp_provider::McpConfig::from_file(path) {
            Ok(c) => c,
            Err(e) => {
                eprintln!("{}", e);
                return 1;
            }
        };
        let rt = tokio::runtime::Builder::new_current_thread()
            .enable_all()
            .build()
            .expect("tokio runtime");
        let provider = match rt.block_on(tools::mcp_provider::McpProvider::connect(&config)) {
            Ok(p) => p,
            Err(e) => {
                eprintln!("MCP error: {}", e);
                return 1;
            }
        };
        let mut decls = provider.tool_decls();
        decls.append(&mut program.declarations);
        program.declarations = decls;
        mcp_rt = Some(rt);
        mcp_provider_holder = Some(provider);
    }

    let mut had_errors = false;

    // Resolve imports
    {
        let base_dir: Option<std::path::PathBuf> = if is_file {
            std::path::Path::new(source_arg)
                .canonicalize()
                .ok()
                .and_then(|p| p.parent().map(|d| d.to_path_buf()))
        } else {
            None
        };
        let mut import_diagnostics: Vec<Diagnostic> = Vec::new();
        let mut visited = std::collections::HashSet::new();
        if let Ok(canonical_file) = std::path::Path::new(source_arg).canonicalize() {
            visited.insert(canonical_file);
        }
        program.declarations = resolve_imports(
            program.declarations,
            base_dir.as_deref(),
            &mut visited,
            &mut import_diagnostics,
            BuildTarget::default(),
        );
        for d in import_diagnostics {
            report_diagnostic(&d, mode);
            had_errors = true;
        }
    }

    for e in &parse_errors {
        report_diagnostic(&Diagnostic::from(e).with_source(source.clone()), mode);
        had_errors = true;
    }

    // AST-dump mode: explicit (`--ast`) OR the legacy inline-no-func default
    // (`ilo '<code>'` with no entry point and no other mode flag). This is an
    // inspection path, not an execution path, so verify (which exists to gate
    // execution) shouldn't gate it. Skipping verify here also avoids
    // false-positive errors on builtins or partial snippets that users want to
    // explore via the AST dump. Parse errors still gate (we can't dump an AST
    // we couldn't parse).
    //
    // Auto-run carve-out (PR #257-era regression fix): commit c9e1ed0 made
    // inline `ilo '<code>'` auto-run when there's a runnable entry (`main`
    // or a single user-defined fn). Those runs MUST go through verify, or
    // shapes like bare-ident bang (`x=42;x!`) reach the interpreter
    // unverified and silently return nil. Only suppress verify when the
    // snippet will actually AST-dump: zero user fns, or multi-fns without
    // a `main`. Mirror the auto-run heuristic at the dispatch site below.
    let user_fn_names: Vec<&str> = program
        .declarations
        .iter()
        .filter_map(|d| match d {
            ast::Decl::Function { name, .. } if !name.starts_with("__") => Some(name.as_str()),
            _ => None,
        })
        .collect();
    let inline_will_auto_run = !is_file
        && r.rest.is_empty()
        && matches!(r.effective_engine(), cli::Engine::Default)
        && (user_fn_names.len() == 1 || user_fn_names.contains(&"main"));
    let ast_dump_mode = r.ast
        || (!is_file
            && r.rest.is_empty()
            && !r.bench
            && !r.explain
            && r.emit.is_none()
            && !r.dense
            && !r.expanded
            && matches!(r.effective_engine(), cli::Engine::Default)
            && !inline_will_auto_run);

    if !ast_dump_mode {
        let verify_result = verify::verify(&program);
        for w in &verify_result.warnings {
            report_diagnostic(&Diagnostic::from(w).with_source(source.clone()), mode);
        }
        if !verify_result.errors.is_empty() {
            for e in &verify_result.errors {
                report_diagnostic(&Diagnostic::from(e).with_source(source.clone()), mode);
            }
            had_errors = true;
        }
    }

    if had_errors {
        return 1;
    }

    // Dispatch based on mode flags
    let exit_code = if r.bench {
        let func_name = r.rest.first().map(|s| s.as_str());
        let raw = if r.rest.len() > 1 {
            &r.rest[1..]
        } else {
            &[][..]
        };
        let run_args = parse_cli_args_typed(&program, func_name, raw);
        let json = matches!(mode, OutputMode::Json);
        run_bench(&program, func_name, &run_args, json, silent);
        0
    } else if r.explain {
        let filename = if is_file {
            Some(source_arg.as_str())
        } else {
            None
        };
        print!("{}", codegen::explain::explain(&program, filename));
        0
    } else if let Some(ref target) = r.emit {
        // Stage 5c (manifesto-strict CLI): `--emit <target>` is removed.
        // The canonical form is now `ilo build <file> --<target>`. For
        // python this means `ilo build file.ilo --py`. Print a migration
        // hint and exit 2 so scripts notice the breakage immediately.
        // Per Stage 5c the legacy --emit path is a migration hint only.
        if target == "python" {
            eprintln!(
                "error: `--emit python` is removed. Use `ilo build <file.ilo> --py` instead."
            );
        } else if target == "js" {
            // JS emit retained for now via codegen::js.
            println!("{}", codegen::js::emit(&program));
        } else {
            eprintln!("Unknown emit target. Supported: python (use --py), js");
        }
        2
    } else if r.dense {
        println!(
            "{}",
            codegen::fmt::format(&program, codegen::fmt::FmtMode::Dense)
        );
        0
    } else if r.expanded {
        print!(
            "{}",
            codegen::fmt::format(&program, codegen::fmt::FmtMode::Expanded)
        );
        0
    } else {
        // Execution dispatch based on engine
        let engine = r.effective_engine();
        let rest = &r.rest;

        match engine {
            cli::Engine::Cranelift => {
                run_cranelift_engine(&program, rest, &source, mode, explicit_json)
            }
            cli::Engine::Llvm => run_llvm_engine(&program, rest),
            cli::Engine::Vm => {
                let (func_name, raw) = resolve_engine_func_name(&program, rest);
                let run_args = parse_cli_args_typed(&program, func_name, raw);
                // CLI-boundary arity guard. The bytecode VM's `setup_call`
                // pads missing args with `NanVal::nil()` and silently
                // ignores extras (vm/mod.rs:5996), so without this gate the
                // user gets a `nil` result for a missing positional. See
                // `check_cli_arity` doc + run_default for the regression
                // history.
                if let Err(code) =
                    check_cli_arity(&program, func_name, run_args.len(), &source, mode)
                {
                    return code;
                }
                let compiled = match vm::compile(&program) {
                    Ok(c) => c,
                    Err(e) => {
                        eprintln!("Compile error: {}", e);
                        return 1;
                    }
                };
                let suppress = program_result_should_suppress(&program, func_name);
                run_vm_with_provider(
                    &compiled,
                    func_name,
                    run_args,
                    tools_config_path.as_deref(),
                    #[cfg(feature = "tools")]
                    mcp_provider_holder.as_ref(),
                    #[cfg(feature = "tools")]
                    mcp_rt.as_ref(),
                    &source,
                    mode,
                    explicit_json,
                    suppress,
                    caps,
                )
            }
            cli::Engine::Default => {
                // Default: func-name heuristic + bytecode register VM (closure-aware,
                // all opcodes supported). Cranelift JIT is opt-in via --jit /
                // --jit; tree interpreter is the canonical-semantics fallback
                // for any program the VM rejects.
                //
                // Inline-lambda lifting emits synthetic `__lit_N` top-level
                // decls (see parser/mod.rs ~line 2863). These are an
                // implementation detail of HOF dispatch — they must not show
                // up in the "available functions" listing, must not satisfy
                // the auto-run heuristic, and must not be selectable as a
                // CLI positional arg. The `__` prefix is reserved for the
                // compiler; filtering on it is safe.
                let func_names: Vec<&str> = program
                    .declarations
                    .iter()
                    .filter_map(|d| match d {
                        ast::Decl::Function { name, .. } if !name.starts_with("__") => {
                            Some(name.as_str())
                        }
                        _ => None,
                    })
                    .collect();

                // Explicit AST dump (`--ast`) takes precedence over everything.
                if r.ast {
                    return dump_ast_json(&program);
                }

                let (func_name, run_args) = if let Some(first) = rest.first() {
                    if func_names.contains(&first.as_str()) {
                        let fn_ref = Some(first.as_str());
                        (fn_ref, parse_cli_args_typed(&program, fn_ref, &rest[1..]))
                    } else if is_file && func_names.len() > 1 && looks_like_subcommand_name(first) {
                        // Multi-function file with an unknown leading
                        // positional that LOOKS like an identifier
                        // (alphabetic / underscore start, ident-shaped
                        // tail): this is almost certainly a mistyped
                        // subcommand, not a literal arg to the first
                        // function. Silently routing to the first
                        // declared function with `[unknown, ...]` as
                        // args produced a misleading arity error far
                        // from the cause (interactive-cli rerun5 P1).
                        //
                        // The ident-shaped guard preserves the existing
                        // pass-through for numeric / sigil-shaped
                        // leading args, which are clearly data, not a
                        // subcommand attempt (e.g. `ilo file.ilo 42`
                        // still routes `42` to the first fn — see
                        // `tests/eval_inline.rs` unwrap_*_inline).
                        //
                        // Synthetic `__lit_*` decls are already filtered
                        // out of `func_names` above (see #307), so the
                        // listing here only shows user functions.
                        eprintln!("error: no such function '{}' in {}", first, source_arg);
                        eprintln!("available functions:");
                        for n in &func_names {
                            eprintln!("  {}", n);
                        }
                        eprintln!();
                        eprintln!("  ilo {} <func> [args...]   run a function", source_arg);
                        return 1;
                    } else if is_file && func_names.contains(&"main") {
                        // Multi-function file with an unknown leading
                        // positional that does NOT look ident-shaped (a
                        // path like `top200.csv`, a digit-prefixed
                        // string, a sigil, etc.) and the file defines
                        // `main`: route to `main` with the positional as
                        // arg #1. Previously this fell through to the
                        // "first declared function" path, so
                        // `ilo main_v5.ilo top200.csv` ran the first
                        // alphabetical/declared function (e.g. `hav`)
                        // with `top200.csv` as its first arg — a
                        // misleading silent mis-dispatch when the user
                        // clearly intended `main` as the entry point
                        // (gis-analyst rerun6, devops-sre rerun6 —
                        // independent personas, same root cause). The
                        // presence of `main` is the strong intent
                        // signal; we use it wherever the user has not
                        // explicitly named a different function.
                        let fn_ref = Some("main");
                        (fn_ref, parse_cli_args_typed(&program, fn_ref, rest))
                    } else {
                        (None, rest.iter().map(|a| parse_cli_arg(a)).collect())
                    }
                } else if is_file {
                    // File with no func arg: auto-run if there's exactly one
                    // function, auto-run `main` if a multi-fn file defines
                    // one, list available functions if there are several
                    // without a `main`, AST-dump if there are none
                    // (declarations-only file — useful for inspecting
                    // type/alias-only modules). SKILL.md documents the
                    // main-as-default convention; see `[CLI invocation]`.
                    match func_names.len() {
                        0 => return dump_ast_json(&program),
                        1 => (None, vec![]),
                        _ if func_names.contains(&"main") => (Some("main"), vec![]),
                        _ => {
                            eprintln!(
                                "error: {} defines multiple functions, please specify one.",
                                source_arg
                            );
                            eprintln!("available functions:");
                            for n in &func_names {
                                eprintln!("  {}", n);
                            }
                            eprintln!();
                            eprintln!("  ilo {} <func> [args...]   run a function", source_arg);
                            eprintln!(
                                "  ilo --ast {}              dump the parsed AST as JSON",
                                source_arg
                            );
                            return 1;
                        }
                    }
                } else {
                    // Inline code with no func arg and no other mode flag.
                    //
                    // SKILL.md documents: "Inline programs (`ilo 'code'`)
                    // and single-function files run their entry function
                    // with the remaining CLI args; no explicit function
                    // name needed." Auto-run when there's a runnable
                    // target: a function called `main`, or a single
                    // user-defined function.
                    //
                    // Silently AST-dumping a runnable inline program was a
                    // soundness hazard for piped consumers — they got
                    // valid-looking JSON on stdout with exit code 0 that
                    // was NOT the program result.
                    //
                    // Zero-fn or multi-fn-without-main inline snippets
                    // still AST-dump, preserving the tooling escape hatch
                    // from PR #178. `--ast` remains the explicit form for
                    // pinning AST-dump output regardless of fn shape.
                    match func_names.len() {
                        0 => return dump_ast_json(&program),
                        1 => (None, vec![]),
                        _ if func_names.contains(&"main") => (Some("main"), vec![]),
                        _ => return dump_ast_json(&program),
                    }
                };

                run_default(
                    &program,
                    func_name,
                    run_args,
                    &source,
                    mode,
                    explicit_json,
                    caps,
                )
            }
        }
    };

    // Emit idiomatic hints after successful execution
    if exit_code == 0 && !no_hints {
        let hints = collect_hints_with_program(&source, Some(&program));
        emit_hints(&hints, mode);
    }

    exit_code
}

/// Cranelift JIT engine dispatch. Returns exit code.
fn run_cranelift_engine(
    program: &ast::Program,
    rest: &[String],
    source: &str,
    mode: OutputMode,
    explicit_json: bool,
) -> i32 {
    let (func_name, raw) = resolve_engine_func_name(program, rest);
    let run_args = parse_cli_args_typed(program, func_name, raw);
    // CLI-boundary arity guard (mirrors run_default). See the comment there
    // for the regression history; same contract applies to the explicit
    // --jit dispatch path.
    if let Err(code) = check_cli_arity(program, func_name, run_args.len(), source, mode) {
        return code;
    }
    let suppress = program_result_should_suppress(program, func_name);

    #[cfg(feature = "cranelift")]
    {
        let compiled = match vm::compile(program) {
            Ok(c) => c,
            Err(e) => {
                eprintln!("Compile error: {}", e);
                return 1;
            }
        };
        let target_name = func_name.unwrap_or(
            compiled
                .func_names
                .first()
                .map(|s| s.as_str())
                .unwrap_or("main"),
        );
        let func_idx = match compiled.func_names.iter().position(|n| n == target_name) {
            Some(i) => i,
            None => {
                eprintln!("undefined function: {}", target_name);
                return 1;
            }
        };
        let chunk = &compiled.chunks[func_idx];
        let nan_consts = &compiled.nan_constants[func_idx];
        let nan_args: Vec<u64> = run_args
            .iter()
            .map(|v| vm::NanVal::from_value_with_program(v, &compiled.func_names).0)
            .collect();
        match vm::jit_cranelift::compile_and_call(chunk, nan_consts, &nan_args, &compiled) {
            Ok(result_bits) => {
                // Use the program-aware bridge so user-fn FnRefs in the
                // returned value resolve back to their source names
                // rather than the synthetic `<user_fn:N>` placeholder.
                // `with_active_registry` clears its TLS on return, so
                // we cannot lean on the implicit context here.
                let result = vm::NanVal(result_bits).to_value_with_program(&compiled.func_names);
                print_value(&result, explicit_json, suppress);
                program_exit_code(&result)
            }
            Err(vm::jit_cranelift::JitCallError::Runtime(e)) => {
                report_diagnostic(&Diagnostic::from(&e).with_source(source.to_string()), mode);
                1
            }
            Err(vm::jit_cranelift::JitCallError::NotEligible) => {
                // The JIT bailed on this function — typically because it
                // contains an opcode the JIT cannot or should not compile
                // (e.g. OP_WINDOW / OP_WINDOW_VIEW after the PR-2 listview
                // reshape, see jit_cranelift.rs:2443). Fall back to the
                // bytecode VM, which is the closest-performance tier and
                // remains sound for the VM-only opcodes the JIT bailed on.
                // The user asked for Cranelift but the program doesn't fit
                // the JIT's input language; failing outright would be a
                // worse experience than silently running on the VM.
                match vm::run(&compiled, func_name, run_args) {
                    Ok(val) => {
                        print_value(&val, explicit_json, suppress);
                        program_exit_code(&val)
                    }
                    Err(e) => {
                        report_diagnostic(
                            &Diagnostic::from(&e).with_source(source.to_string()),
                            mode,
                        );
                        1
                    }
                }
            }
            Err(vm::jit_cranelift::JitCallError::Panic { msg }) => {
                // Upstream cranelift-jit 0.116 has an AArch64 near-call
                // relocation assertion (`compiled_blob.rs:90`) that fires
                // non-deterministically when the JIT code-cache and runtime
                // memory get laid out >±64 MB apart. Converting the process
                // crash to a single-line stderr breadcrumb + VM fallback
                // preserves the working pipeline while keeping the upstream
                // issue visible. The user asked for Cranelift explicitly, so
                // we note the engine swap; we fall back to the bytecode VM
                // (the closest non-JIT performance tier) rather than the
                // tree interpreter. `note_jit_panic_fallback` emits a
                // tagged, flushed, once-per-process breadcrumb that
                // persona harnesses can grep for reliably even when they
                // merge or buffer stderr.
                vm::jit_cranelift::note_jit_panic_fallback(&msg, "bytecode VM");
                match vm::run(&compiled, func_name, run_args) {
                    Ok(val) => {
                        print_value(&val, explicit_json, suppress);
                        program_exit_code(&val)
                    }
                    Err(e) => {
                        report_diagnostic(
                            &Diagnostic::from(&e).with_source(source.to_string()),
                            mode,
                        );
                        1
                    }
                }
            }
        }
    }
    #[cfg(not(feature = "cranelift"))]
    {
        let _ = (func_name, run_args, source, mode, explicit_json, suppress);
        eprintln!("Cranelift JIT not enabled. Build with: cargo build --features cranelift");
        1
    }
}

/// LLVM JIT engine dispatch. Returns exit code.
fn run_llvm_engine(_program: &ast::Program, rest: &[String]) -> i32 {
    let func_name = rest.first().map(|s| s.as_str());
    let jit_args: Vec<f64> = if rest.len() > 1 {
        let mut args = Vec::new();
        for a in &rest[1..] {
            match a.parse::<f64>() {
                Ok(v) => args.push(v),
                Err(_) => {
                    eprintln!("error: JIT argument '{}' is not a valid number", a);
                    return 1;
                }
            }
        }
        args
    } else {
        vec![]
    };

    #[cfg(feature = "llvm")]
    {
        let compiled = match vm::compile(program) {
            Ok(c) => c,
            Err(e) => {
                eprintln!("Compile error: {}", e);
                return 1;
            }
        };
        let target_name = func_name.unwrap_or(
            compiled
                .func_names
                .first()
                .map(|s| s.as_str())
                .unwrap_or("main"),
        );
        let func_idx = match compiled.func_names.iter().position(|n| n == target_name) {
            Some(i) => i,
            None => {
                eprintln!("undefined function: {}", target_name);
                return 1;
            }
        };
        let chunk = &compiled.chunks[func_idx];
        let nan_consts = &compiled.nan_constants[func_idx];
        match vm::jit_llvm::compile_and_call(chunk, nan_consts, &jit_args) {
            Some(result) => {
                if result == (result as i64) as f64 {
                    println!("{}", result as i64);
                } else {
                    println!("{}", result);
                }
                0
            }
            None => {
                eprintln!("LLVM JIT: function not eligible for compilation");
                1
            }
        }
    }
    #[cfg(not(feature = "llvm"))]
    {
        let _ = (func_name, jit_args);
        eprintln!("LLVM JIT not enabled. Build with: cargo build --features llvm");
        1
    }
}

